    def get_search_fields(self, request):
        """
        Return a sequence containing the fields to be searched whenever
        somebody submits a search query.
        """
        return self.search_fields

    def get_search_results(self, request, queryset, search_term):
        """
        Return a tuple containing a queryset to implement the search
        and a boolean indicating if the results may contain duplicates.
        """

        # Apply keyword searches.
        def construct_search(field_name):
            """
            Return a tuple of (lookup, field_to_validate).

            field_to_validate is set for non-text exact lookups so that
            invalid search terms can be skipped (preserving index usage).
            """
            if field_name.startswith("^"):
                return "%s__istartswith" % field_name.removeprefix("^"), None
            elif field_name.startswith("="):
                return "%s__iexact" % field_name.removeprefix("="), None
            elif field_name.startswith("@"):
                return "%s__search" % field_name.removeprefix("@"), None
            # Use field_name if it includes a lookup.
            opts = queryset.model._meta
            lookup_fields = field_name.split(LOOKUP_SEP)
            # Go through the fields, following all relations.
            prev_field = None
            for path_part in lookup_fields:
                if path_part == "pk":
                    path_part = opts.pk.name
                try:
                    field = opts.get_field(path_part)
                except FieldDoesNotExist:
                    # Use valid query lookups.
                    if prev_field and prev_field.get_lookup(path_part):
                        if path_part == "exact" and not isinstance(
                            prev_field, (models.CharField, models.TextField)
                        ):
                            # Use prev_field to validate the search term.
                            return field_name, prev_field
                        return field_name, None
                else:
                    prev_field = field
                    if hasattr(field, "path_infos"):
                        # Update opts to follow the relation.
                        opts = field.path_infos[-1].to_opts
            # Otherwise, use the field with icontains.
            return "%s__icontains" % field_name, None

        may_have_duplicates = False
        search_fields = self.get_search_fields(request)
        if search_fields and search_term:
            orm_lookups = []
            for field in search_fields:
                orm_lookups.append(construct_search(str(field)))

            term_queries = []
            for bit in smart_split(search_term):
                if bit.startswith(('"', "'")) and bit[0] == bit[-1]:
                    bit = unescape_string_literal(bit)
                # Build term lookups, skipping values invalid for their field.
                bit_lookups = []
                for orm_lookup, validate_field in orm_lookups:
                    if validate_field is not None:
                        formfield = validate_field.formfield()
                        try:
                            if formfield is not None:
                                value = formfield.to_python(bit)
                            else:
                                # Fields like AutoField lack a form field.
                                value = validate_field.to_python(bit)
                        except ValidationError:
                            # Skip this lookup for invalid values.
                            continue
                    else:
                        value = bit
                    bit_lookups.append((orm_lookup, value))
                if bit_lookups:
                    or_queries = models.Q.create(bit_lookups, connector=models.Q.OR)
                    term_queries.append(or_queries)
                else:
                    # No valid lookups: add a filter that returns nothing.
                    term_queries.append(models.Q(pk__in=[]))
            if term_queries:
                queryset = queryset.filter(models.Q.create(term_queries))
            may_have_duplicates |= any(
                lookup_spawns_duplicates(self.opts, search_spec)
                for search_spec, _ in orm_lookups
            )
        return queryset, may_have_duplicates

    def get_preserved_filters(self, request):
        """
        Return the preserved filters querystring.
        """
        match = request.resolver_match
        if self.preserve_filters and match:
            current_url = "%s:%s" % (match.app_name, match.url_name)
            changelist_url = "admin:%s_%s_changelist" % (
                self.opts.app_label,
                self.opts.model_name,
            )
            if current_url == changelist_url:
                preserved_filters = request.GET.urlencode()
            else:
                preserved_filters = request.GET.get("_changelist_filters")

            if preserved_filters:
                return urlencode({"_changelist_filters": preserved_filters})
        return ""

    def construct_change_message(self, request, form, formsets, add=False):
        """
        Construct a JSON structure describing changes from a changed object.
        """
        return construct_change_message(form, formsets, add)

    def message_user(
        self, request, message, level=messages.INFO, extra_tags="", fail_silently=False
    ):
        """
        Send a message to the user. The default implementation
        posts a message using the django.contrib.messages backend.

        Exposes almost the same API as messages.add_message(), but accepts the
        positional arguments in a different order to maintain backwards
        compatibility. For convenience, it accepts the `level` argument as
        a string rather than the usual level number.
        """
        if not isinstance(level, int):
            # attempt to get the level if passed a string
            try:
                level = getattr(messages.constants, level.upper())
            except AttributeError:
                levels = messages.constants.DEFAULT_TAGS.values()
                levels_repr = ", ".join("`%s`" % level for level in levels)
                raise ValueError(
                    "Bad message level string: `%s`. Possible values are: %s"
                    % (level, levels_repr)
                )

        messages.add_message(
            request, level, message, extra_tags=extra_tags, fail_silently=fail_silently
        )

    def save_form(self, request, form, change):
        """
        Given a ModelForm return an unsaved instance. ``change`` is True if
        the object is being changed, and False if it's being added.
        """
        return form.save(commit=False)

    def save_model(self, request, obj, form, change):
        """
        Given a model instance save it to the database.
        """
        obj.save()

    def delete_model(self, request, obj):
        """
        Given a model instance delete it from the database.
        """
        obj.delete()

    def delete_queryset(self, request, queryset):
        """Given a queryset, delete it from the database."""
        queryset.delete()

    def save_formset(self, request, form, formset, change):
        """
        Given an inline formset save it to the database.
        """
        formset.save()

    def save_related(self, request, form, formsets, change):
        """
        Given the ``HttpRequest``, the parent ``ModelForm`` instance, the
        list of inline formsets and a boolean value based on whether the
        parent is being added or changed, save the related objects to the
        database. Note that at this point save_form() and save_model() have
        already been called.
        """
        form.save_m2m()
        for formset in formsets:
            self.save_formset(request, form, formset, change=change)

    def render_change_form(
        self, request, context, add=False, change=False, form_url="", obj=None
    ):
        app_label = self.opts.app_label
        preserved_filters = self.get_preserved_filters(request)
        form_url = add_preserved_filters(
            {"preserved_filters": preserved_filters, "opts": self.opts}, form_url
        )
        view_on_site_url = self.get_view_on_site_url(obj)
        has_editable_inline_admin_formsets = False
        for inline in context["inline_admin_formsets"]:
            if (
                inline.has_add_permission
                or inline.has_change_permission
                or inline.has_delete_permission
            ):
                has_editable_inline_admin_formsets = True
                break
        context.update(
            {
                "add": add,
                "change": change,
                "has_view_permission": self.has_view_permission(request, obj),
                "has_add_permission": self.has_add_permission(request),
                "has_change_permission": self.has_change_permission(request, obj),
                "has_delete_permission": self.has_delete_permission(request, obj),
                "has_editable_inline_admin_formsets": (
                    has_editable_inline_admin_formsets
                ),
                "has_file_field": context["adminform"].form.is_multipart()
                or any(
                    admin_formset.formset.is_multipart()
                    for admin_formset in context["inline_admin_formsets"]
                ),
                "has_absolute_url": view_on_site_url is not None,
                "absolute_url": view_on_site_url,
                "form_url": form_url,
                "opts": self.opts,
                "content_type_id": get_content_type_for_model(self.model).pk,
                "save_as": self.save_as,
                "save_on_top": self.save_on_top,
                "to_field_var": TO_FIELD_VAR,
                "is_popup_var": IS_POPUP_VAR,
                "source_model_var": SOURCE_MODEL_VAR,
                "app_label": app_label,
            }
        )
        if add and self.add_form_template is not None:
            form_template = self.add_form_template
        else:
            form_template = self.change_form_template

        request.current_app = self.admin_site.name

        return TemplateResponse(
            request,
            form_template
            or [
                "admin/%s/%s/change_form.html" % (app_label, self.opts.model_name),
                "admin/%s/change_form.html" % app_label,
                "admin/change_form.html",
            ],
            context,
        )

    def _get_preserved_qsl(self, request, preserved_filters):
        query_string = urlsplit(request.build_absolute_uri()).query
        return parse_qsl(query_string.replace(preserved_filters, ""))

    def response_add(self, request, obj, post_url_continue=None):
        """
        Determine the HttpResponse for the add_view stage.
        """
        opts = obj._meta
        preserved_filters = self.get_preserved_filters(request)
        preserved_qsl = self._get_preserved_qsl(request, preserved_filters)
        obj_url = reverse(
            "admin:%s_%s_change" % (opts.app_label, opts.model_name),
            args=(quote(obj.pk),),
            current_app=self.admin_site.name,
        )
        # Add a link to the object's change form if the user can edit the obj.
        obj_display = display_for_value(str(obj), EMPTY_VALUE_STRING)
        if self.has_change_permission(request, obj):
            obj_repr = format_html(
                '<a href="{}">{}</a>', urlquote(obj_url), obj_display
            )
        else:
            obj_repr = obj_display
        msg_dict = {
            "name": opts.verbose_name,
            "obj": obj_repr,
        }
        # Here, we distinguish between different save types by checking for
        # the presence of keys in request.POST.

        if IS_POPUP_VAR in request.POST:
            to_field = request.POST.get(TO_FIELD_VAR)
            if to_field:
                attr = str(to_field)
            else:
                attr = obj._meta.pk.attname
            value = obj.serializable_value(attr)
            popup_response = {
                "value": str(value),
                "obj": str(obj),
            }

            # Find the optgroup for the new item, if available
            source_model_name = request.POST.get(SOURCE_MODEL_VAR)
            source_admin = None
            if source_model_name:
                try:
                    app_label, model_name = source_model_name.split(".", 1)
                    source_model = apps.get_model(app_label, model_name)
                except (LookupError, ValueError):
                    msg = _('The app "%s" could not be found.') % source_model_name
                    self.message_user(request, msg, messages.ERROR)
                else:
                    source_admin = self.admin_site._registry.get(source_model)

            if source_admin:
                form = source_admin.get_form(request)()
                if self.opts.verbose_name_plural in form.fields:
                    field = form.fields[self.opts.verbose_name_plural]
                    for option_value, option_label in field.choices:
                        # Check if this is an optgroup (label is a sequence
                        # of choices rather than a single string value).
                        if isinstance(option_label, (list, tuple)):
                            # It's an optgroup:
                            # (group_name, [(value, label), ...])
                            optgroup_label = option_value
                            for choice_value, choice_display in option_label:
                                if choice_display == str(obj):
                                    popup_response["optgroup"] = str(optgroup_label)
                                    break

            popup_response_data = json.dumps(popup_response)
            return TemplateResponse(
                request,
                self.popup_response_template
                or [
                    "admin/%s/%s/popup_response.html"
                    % (opts.app_label, opts.model_name),
                    "admin/%s/popup_response.html" % opts.app_label,
                    "admin/popup_response.html",
                ],
                {
                    "popup_response_data": popup_response_data,
                },
            )

        elif "_continue" in request.POST or (
            # Redirecting after "Save as new".
            "_saveasnew" in request.POST
            and self.save_as_continue
            and self.has_change_permission(request, obj)
        ):
            msg = _("The {name} “{obj}” was added successfully.")
            if self.has_change_permission(request, obj):
                msg += " " + _("You may edit it again below.")
            self.message_user(request, format_html(msg, **msg_dict), messages.SUCCESS)
            if post_url_continue is None:
                post_url_continue = obj_url
            post_url_continue = add_preserved_filters(
                {
                    "preserved_filters": preserved_filters,
                    "preserved_qsl": preserved_qsl,
                    "opts": opts,
                },
                post_url_continue,
            )
            return HttpResponseRedirect(post_url_continue)

        elif "_addanother" in request.POST:
            msg = format_html(
                _(
                    "The {name} “{obj}” was added successfully. You may add another "
                    "{name} below."
                ),
                **msg_dict,
            )
            self.message_user(request, msg, messages.SUCCESS)
            redirect_url = request.path
            redirect_url = add_preserved_filters(
                {
                    "preserved_filters": preserved_filters,
                    "preserved_qsl": preserved_qsl,
                    "opts": opts,
                },
                redirect_url,
            )
            return HttpResponseRedirect(redirect_url)

        else:
            msg = format_html(
                _("The {name} “{obj}” was added successfully."), **msg_dict
            )
            self.message_user(request, msg, messages.SUCCESS)
            return self.response_post_save_add(request, obj)

    def response_change(self, request, obj):
        """
        Determine the HttpResponse for the change_view stage.
        """

        if IS_POPUP_VAR in request.POST:
            opts = obj._meta
            to_field = request.POST.get(TO_FIELD_VAR)
            attr = str(to_field) if to_field else opts.pk.attname
            value = request.resolver_match.kwargs["object_id"]
            new_value = obj.serializable_value(attr)
            popup_response_data = json.dumps(
                {
                    "action": "change",
                    "value": str(value),
                    "obj": str(obj),
                    "new_value": str(new_value),
                }
            )
            return TemplateResponse(
                request,
                self.popup_response_template
                or [
                    "admin/%s/%s/popup_response.html"
                    % (opts.app_label, opts.model_name),
                    "admin/%s/popup_response.html" % opts.app_label,
                    "admin/popup_response.html",
                ],
                {
                    "popup_response_data": popup_response_data,
                },
            )

        opts = self.opts
        preserved_filters = self.get_preserved_filters(request)
        preserved_qsl = self._get_preserved_qsl(request, preserved_filters)

        obj_display = display_for_value(str(obj), EMPTY_VALUE_STRING)
        msg_dict = {
            "name": opts.verbose_name,
            "obj": format_html(
                '<a href="{}">{}</a>', urlquote(request.path), obj_display
            ),
        }
        if "_continue" in request.POST:
            msg = format_html(
                _(
                    "The {name} “{obj}” was changed successfully. You may edit it "
                    "again below."
                ),
                **msg_dict,
            )
            self.message_user(request, msg, messages.SUCCESS)
            redirect_url = request.path
            redirect_url = add_preserved_filters(
                {
                    "preserved_filters": preserved_filters,
                    "preserved_qsl": preserved_qsl,
                    "opts": opts,
                },
                redirect_url,
            )
            return HttpResponseRedirect(redirect_url)

        elif "_addanother" in request.POST:
            msg = format_html(
                _(
                    "The {name} “{obj}” was changed successfully. You may add another "
                    "{name} below."
                ),
                **msg_dict,
            )
            self.message_user(request, msg, messages.SUCCESS)
            redirect_url = reverse(
                "admin:%s_%s_add" % (opts.app_label, opts.model_name),
                current_app=self.admin_site.name,
            )
            redirect_url = add_preserved_filters(
                {
                    "preserved_filters": preserved_filters,
                    "preserved_qsl": preserved_qsl,
                    "opts": opts,
                },
                redirect_url,
            )
            return HttpResponseRedirect(redirect_url)

        else:
            msg = format_html(
                _("The {name} “{obj}” was changed successfully."), **msg_dict
            )
            self.message_user(request, msg, messages.SUCCESS)
            return self.response_post_save_change(request, obj)

    def _response_post_save(self, request, obj):
        if self.has_view_or_change_permission(request):
            post_url = reverse(
                "admin:%s_%s_changelist" % (self.opts.app_label, self.opts.model_name),
                current_app=self.admin_site.name,
            )
            preserved_filters = self.get_preserved_filters(request)
            post_url = add_preserved_filters(
                {"preserved_filters": preserved_filters, "opts": self.opts}, post_url
            )
        else:
            post_url = reverse("admin:index", current_app=self.admin_site.name)
        return HttpResponseRedirect(post_url)

    def response_post_save_add(self, request, obj):
        """
        Figure out where to redirect after the 'Save' button has been pressed
        when adding a new object.
        """
        return self._response_post_save(request, obj)

    def response_post_save_change(self, request, obj):
        """
        Figure out where to redirect after the 'Save' button has been pressed
        when editing an existing object.
        """
        return self._response_post_save(request, obj)

    def response_action(
        self, request, queryset, action_location=ActionLocation.CHANGE_LIST
    ):
        """
        Handle an admin action. Returns an HttpResponse if the action was
        handled, and None otherwise.
        """

        # There can be multiple action forms on the page (at the top
        # and bottom of the change list, for example). Get the action
        # whose button was pushed.
        try:
            action_index = int(request.POST.get("index", 0))
        except ValueError:
            action_index = 0

        # Construct the action form.
        data = request.POST.copy()
        data.pop(helpers.ACTION_CHECKBOX_NAME, None)
        data.pop("index", None)

        # Use the action whose button was pushed
        try:
            data.update({"action": data.getlist("action")[action_index]})
        except IndexError:
            # If we didn't get an action from the chosen form that's invalid
            # POST data, so by deleting action it'll fail the validation check
            # below. So no need to do anything here
            pass

        prefix = (
            action_location.value
            if action_location != ActionLocation.CHANGE_LIST
            else ""
        )
        action_form = self.action_form(data, auto_id=None, prefix=prefix)
        # RemovedInDjango70Warning: When the deprecation ends, replace with:
        # action_form.fields["action"].choices = self.get_action_choices(
        #     request, action_location=action_location
        # )
        action_form.fields["action"].choices = (
            self._get_action_choices_with_action_location(
                request, action_location=action_location
            )
        )

        # If the form's valid we can handle the action.
        if action_form.is_valid():
            action = action_form.cleaned_data["action"]
            select_across = action_form.cleaned_data["select_across"]
            if action_location == ActionLocation.CHANGE_FORM:
                select_across = False
            # RemovedInDjango70Warning: When the deprecation ends, replace:
            # actions = self.get_actions(
            #     request, action_location=action_location
            # )
            actions = self._get_actions_with_action_location(
                request, action_location=action_location
            )
            if isinstance(actions[action], tuple):
                func = actions[action][0]
            else:
                func = actions[action].func

            # Get the list of selected PKs. If nothing's selected, we can't
            # perform an action on it, so bail. Except we want to perform
            # the action explicitly on all objects.
            selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)
            if not selected and not select_across:
                # Something needs to be selected or nothing will happen.
                msg = _(
                    "Items must be selected in order to perform "
                    "actions on them. No items have been changed."
                )
                self.message_user(request, msg, messages.WARNING)
                return None

            if not select_across:
                # Perform the action only on the selected objects
                queryset = queryset.filter(pk__in=selected)

            response = func(self, request, queryset)

            # Actions may return an HttpResponse-like object, which will be
            # used as the response from the POST. If not, we'll be a good
            # little HTTP citizen and redirect back to the changelist page.
            if isinstance(response, HttpResponseBase):
                return response
            else:
                return HttpResponseRedirect(request.get_full_path())
        else:
            msg = _("No action selected.")
            self.message_user(request, msg, messages.WARNING)
            return None

    def response_delete(self, request, obj_display, obj_id):
        """
        Determine the HttpResponse for the delete_view stage.
        """
        if IS_POPUP_VAR in request.POST:
            popup_response_data = json.dumps(
                {
                    "action": "delete",
                    "value": str(obj_id),
                }
            )
            return TemplateResponse(
                request,
                self.popup_response_template
                or [
                    "admin/%s/%s/popup_response.html"
                    % (self.opts.app_label, self.opts.model_name),
                    "admin/%s/popup_response.html" % self.opts.app_label,
                    "admin/popup_response.html",
                ],
                {
                    "popup_response_data": popup_response_data,
                },
            )

        self.message_user(
            request,
            _("The %(name)s “%(obj)s” was deleted successfully.")
            % {
                "name": self.opts.verbose_name,
                "obj": display_for_value(str(obj_display), EMPTY_VALUE_STRING),
            },
            messages.SUCCESS,
        )

        if self.has_change_permission(request, None):
            post_url = reverse(
                "admin:%s_%s_changelist" % (self.opts.app_label, self.opts.model_name),
                current_app=self.admin_site.name,
            )
            preserved_filters = self.get_preserved_filters(request)
            post_url = add_preserved_filters(
                {"preserved_filters": preserved_filters, "opts": self.opts}, post_url
            )
        else:
            post_url = reverse("admin:index", current_app=self.admin_site.name)
        return HttpResponseRedirect(post_url)

    def render_delete_form(self, request, context):
        app_label = self.opts.app_label

        request.current_app = self.admin_site.name
        context.update(
            to_field_var=TO_FIELD_VAR,
            is_popup_var=IS_POPUP_VAR,
            media=self.media,
        )

        return TemplateResponse(
            request,
            self.delete_confirmation_template
            or [
                "admin/{}/{}/delete_confirmation.html".format(
                    app_label, self.opts.model_name
                ),
                "admin/{}/delete_confirmation.html".format(app_label),
                "admin/delete_confirmation.html",
            ],
            context,
        )

    def get_inline_formsets(self, request, formsets, inline_instances, obj=None):
        # Edit permissions on parent model are required for editable inlines.
        can_edit_parent = (
            self.has_change_permission(request, obj)
            if obj
            else self.has_add_permission(request)
        )
        inline_admin_formsets = []
        for inline, formset in zip(inline_instances, formsets):
            fieldsets = list(inline.get_fieldsets(request, obj))
            readonly = list(inline.get_readonly_fields(request, obj))
            if can_edit_parent:
                has_add_permission = inline.has_add_permission(request, obj)
                has_change_permission = inline.has_change_permission(request, obj)
                has_delete_permission = inline.has_delete_permission(request, obj)
            else:
                # Disable all edit-permissions, and override formset settings.
                has_add_permission = has_change_permission = has_delete_permission = (
                    False
                )
                formset.extra = formset.max_num = 0
            has_view_permission = inline.has_view_permission(request, obj)
            prepopulated = dict(inline.get_prepopulated_fields(request, obj))
            inline_admin_formset = helpers.InlineAdminFormSet(
                inline,
                formset,
                fieldsets,
                prepopulated,
                readonly,
                model_admin=self,
                has_add_permission=has_add_permission,
                has_change_permission=has_change_permission,
                has_delete_permission=has_delete_permission,
                has_view_permission=has_view_permission,
            )
            inline_admin_formsets.append(inline_admin_formset)
        return inline_admin_formsets

    def get_changeform_initial_data(self, request):
        """
        Get the initial form data from the request's GET params.
        """
        initial = dict(request.GET.items())
        for k in initial:
            try:
                f = self.opts.get_field(k)
            except FieldDoesNotExist:
                continue
            # We have to special-case M2Ms as a list of comma-separated PKs.
            if isinstance(f, models.ManyToManyField):
                initial[k] = initial[k].split(",")
        return initial

    def _get_obj_does_not_exist_redirect(self, request, opts, object_id):
        """
        Create a message informing the user that the object doesn't exist
        and return a redirect to the admin index page.
        """
        msg = _("%(name)s with ID “%(key)s” doesn’t exist. Perhaps it was deleted?") % {
            "name": opts.verbose_name,
            "key": unquote(object_id),
        }
        self.message_user(request, msg, messages.WARNING)
        url = reverse("admin:index", current_app=self.admin_site.name)
        return HttpResponseRedirect(url)

    @csrf_protect_m
    def changeform_view(self, request, object_id=None, form_url="", extra_context=None):
        if request.method in ("GET", "HEAD", "OPTIONS", "TRACE"):
            return self._changeform_view(request, object_id, form_url, extra_context)

        with transaction.atomic(using=router.db_for_write(self.model)):
            return self._changeform_view(request, object_id, form_url, extra_context)

    def _changeform_view(self, request, object_id, form_url, extra_context):
        to_field = request.POST.get(TO_FIELD_VAR, request.GET.get(TO_FIELD_VAR))
        if to_field and not self.to_field_allowed(request, to_field):
            raise DisallowedModelAdminToField(
                "The field %s cannot be referenced." % to_field
            )

        if request.method == "POST" and "_saveasnew" in request.POST:
            object_id = None

        add = object_id is None

        if add:
            if not self.has_add_permission(request):
                raise PermissionDenied
            obj = None

        else:
            obj = self.get_object(request, unquote(object_id), to_field)
            if not self.has_view_or_change_permission(request, obj):
                raise PermissionDenied

            if obj is None:
                return self._get_obj_does_not_exist_redirect(
                    request, self.opts, object_id
                )

        action_form = None
        # RemovedInDjango70Warning: When the deprecation ends, replace with:
        # actions = self.get_actions(
        #     request, action_location=ActionLocation.CHANGE_FORM
        # )
        actions = self._get_actions_with_action_location(
            request, action_location=ActionLocation.CHANGE_FORM
        )
        if actions and not add:
            action_location = ActionLocation.CHANGE_FORM
            action_form = self.action_form(auto_id=None, prefix=action_location.value)
            # RemovedInDjango70Warning: When the deprecation ends, replace:
            # action_form.fields["action"].choices = self.get_action_choices(
            #     request, action_location=action_location
            # )
            action_form.fields["action"].choices = (
                self._get_action_choices_with_action_location(
                    request, action_location=action_location
                )
            )
        fieldsets = self.get_fieldsets(request, obj)
        ModelForm = self.get_form(
            request, obj, change=not add, fields=flatten_fieldsets(fieldsets)
        )
        if request.method == "POST":
            if (
                action_form
                and action_form["action"].html_name in request.POST
                and "_save" not in request.POST
                and "_continue" not in request.POST
                and "_addanother" not in request.POST
            ):
                selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)
                if len(selected) != 1 or selected[0] != str(obj.pk):
                    raise BadRequest
                queryset = self.get_queryset(request)
                if response := self.response_action(
                    request, queryset, action_location=ActionLocation.CHANGE_FORM
                ):
                    return response
                return HttpResponseRedirect(request.get_full_path())

            if not add and not self.has_change_permission(request, obj):
                raise PermissionDenied

            form = ModelForm(request.POST, request.FILES, instance=obj)
            formsets, inline_instances = self._create_formsets(
                request,
                form.instance,
                change=not add,
            )
            form_validated = form.is_valid()
            if form_validated:
                new_object = self.save_form(request, form, change=not add)
            else:
                new_object = form.instance
            if all_valid(formsets) and form_validated:
                self.save_model(request, new_object, form, not add)
                self.save_related(request, form, formsets, not add)
                change_message = self.construct_change_message(
                    request, form, formsets, add
                )
                if add:
                    self.log_addition(request, new_object, change_message)
                    return self.response_add(request, new_object)
                else:
                    self.log_change(request, new_object, change_message)
                    return self.response_change(request, new_object)
            else:
                form_validated = False
        else:
            if add:
                initial = self.get_changeform_initial_data(request)
                form = ModelForm(initial=initial)
                formsets, inline_instances = self._create_formsets(
                    request, form.instance, change=False
                )
            else:
                form = ModelForm(instance=obj)
                formsets, inline_instances = self._create_formsets(
                    request, obj, change=True
                )

        if not add and not self.has_change_permission(request, obj):
            readonly_fields = flatten_fieldsets(fieldsets)
        else:
            readonly_fields = self.get_readonly_fields(request, obj)
        admin_form = helpers.AdminForm(
            form,
            list(fieldsets),
            # Clear prepopulated fields on a view-only form to avoid a crash.
            (
                self.get_prepopulated_fields(request, obj)
                if add or self.has_change_permission(request, obj)
                else {}
            ),
            readonly_fields,
            model_admin=self,
        )
        media = self.media + admin_form.media

        inline_formsets = self.get_inline_formsets(
            request, formsets, inline_instances, obj
        )
        for inline_formset in inline_formsets:
            media += inline_formset.media
        if action_form:
            media += action_form.media

        if add:
            title = _("Add %s")
        elif self.has_change_permission(request, obj):
            title = _("Change %s")
        else:
            title = _("View %s")
        context = {
            **self.admin_site.each_context(request),
            "title": title % self.opts.verbose_name,
            "subtitle": (
                display_for_value(str(obj), EMPTY_VALUE_STRING) if obj else None
            ),
            "adminform": admin_form,
            "object_id": object_id,
            "original": obj,
            "is_popup": IS_POPUP_VAR in request.POST or IS_POPUP_VAR in request.GET,
            "source_model": request.GET.get(SOURCE_MODEL_VAR),
            "to_field": to_field,
            "media": media,
            "action_form": action_form,
            "action_checkbox_name": helpers.ACTION_CHECKBOX_NAME,
            "inline_admin_formsets": inline_formsets,
            "errors": helpers.AdminErrorList(form, formsets),
            "preserved_filters": self.get_preserved_filters(request),
        }

        # Hide the "Save" and "Save and continue" buttons if "Save as New" was
        # previously chosen to prevent the interface from getting confusing.
        if (
            request.method == "POST"
            and not form_validated
            and "_saveasnew" in request.POST
        ):
            context["show_save"] = False
            context["show_save_and_continue"] = False
            # Use the change template instead of the add template.
            add = False

        context.update(extra_context or {})

        return self.render_change_form(
            request, context, add=add, change=not add, obj=obj, form_url=form_url
        )

    def add_view(self, request, form_url="", extra_context=None):
        return self.changeform_view(request, None, form_url, extra_context)

    def change_view(self, request, object_id, form_url="", extra_context=None):
        return self.changeform_view(request, object_id, form_url, extra_context)

    def _get_edited_object_pks(self, request, prefix):
        """Return POST data values of list_editable primary keys."""
        pk_pattern = re.compile(
            r"{}-\d+-{}$".format(re.escape(prefix), self.opts.pk.name)
        )
        return [value for key, value in request.POST.items() if pk_pattern.match(key)]

    def _get_list_editable_queryset(self, request, prefix):
        """
        Based on POST data, return a queryset of the objects that were edited
        via list_editable.
        """
        object_pks = self._get_edited_object_pks(request, prefix)
        queryset = self.get_queryset(request)
        validate = queryset.model._meta.pk.to_python
        try:
            for pk in object_pks:
                validate(pk)
        except ValidationError:
            # Disable the optimization if the POST data was tampered with.
            return queryset
        return queryset.filter(pk__in=object_pks)

    def _get_formset_with_permissions(self, request, queryset, for_save=False):
        """
        Construct a changelist formset, and remove list_editable fields
        for objects the user cannot change.
        """
        FormSet = self.get_changelist_formset(request)
        if for_save:
            formset = FormSet(data=request.POST, files=request.FILES, queryset=queryset)
        else:
            formset = FormSet(queryset=queryset)

        for form in formset.forms:
            if not self.has_change_permission(request, form.instance):
                for field_name in self.list_editable:
                    form.fields.pop(field_name, None)

        return formset

    def _save_formset(self, request, formset):
        changecount = 0
        with transaction.atomic(using=router.db_for_write(self.model)):
            for form in formset.forms:
                if not self.has_change_permission(request, form.instance):
                    continue
                if form.has_changed():
                    obj = self.save_form(request, form, change=True)
                    if obj._state.adding:
                        raise BadRequest("list_editable does not allow adding.")
                    self.save_model(request, obj, form, change=True)
                    self.save_related(request, form, formsets=[], change=True)
                    change_msg = self.construct_change_message(request, form, None)
                    self.log_change(request, obj, change_msg)
                    changecount += 1
        if changecount:
            msg = ngettext(
                "%(count)s %(name)s was changed successfully.",
                "%(count)s %(name)s were changed successfully.",
                changecount,
            ) % {
                "count": changecount,
                "name": model_ngettext(self.opts, changecount),
            }
            self.message_user(request, msg, messages.SUCCESS)

    @csrf_protect_m
    def changelist_view(self, request, extra_context=None):
        """
        The 'change list' admin view for this model.
        """
        from django.contrib.admin.views.main import ERROR_FLAG

        app_label = self.opts.app_label
        if not self.has_view_or_change_permission(request):
            raise PermissionDenied

        try:
            cl = self.get_changelist_instance(request)
        except IncorrectLookupParameters:
            # Wacky lookup parameters were given, so redirect to the main
            # changelist page, without parameters, and pass an 'invalid=1'
            # parameter via the query string. If wacky parameters were given
            # and the 'invalid=1' parameter was already in the query string,
            # something is screwed up with the database, so display an error
            # page.
            if ERROR_FLAG in request.GET:
                return SimpleTemplateResponse(
                    "admin/invalid_setup.html",
                    {
                        "title": _("Database error"),
                    },
                )
            return HttpResponseRedirect(request.path + "?" + ERROR_FLAG + "=1")

        # If the request was POSTed, this might be a bulk action or a bulk
        # edit. Try to look up an action or confirmation first, but if this
        # isn't an action the POST will fall through to the bulk edit check,
        # below.
        action_failed = False
        selected = request.POST.getlist(helpers.ACTION_CHECKBOX_NAME)

        # RemovedInDjango70Warning: When the deprecation ends, replace with:
        # actions = self.get_actions(
        #     request, action_location=ActionLocation.CHANGE_LIST
        # )
        actions = self._get_actions_with_action_location(
            request, action_location=ActionLocation.CHANGE_LIST
        )
        # Actions with no confirmation
        if (
            actions
            and request.method == "POST"
            and "index" in request.POST
            and "_save" not in request.POST
        ):
            if selected:
                response = self.response_action(
                    request,
                    queryset=cl.get_queryset(request),
                    action_location=ActionLocation.CHANGE_LIST,
                )
                if response:
                    return response
                else:
                    action_failed = True
            else:
                msg = _(
                    "Items must be selected in order to perform "
                    "actions on them. No items have been changed."
                )
                self.message_user(request, msg, messages.WARNING)
                action_failed = True

        # Actions with confirmation
        if (
            actions
            and request.method == "POST"
            and helpers.ACTION_CHECKBOX_NAME in request.POST
            and "index" not in request.POST
            and "_save" not in request.POST
        ):
            if selected:
                response = self.response_action(
                    request,
                    queryset=cl.get_queryset(request),
                    action_location=ActionLocation.CHANGE_LIST,
                )
                if response:
                    return response
                else:
                    action_failed = True

        if action_failed:
            # Redirect back to the changelist page to avoid resubmitting the
            # form if the user refreshes the browser or uses the "No, take
            # me back" button on the action confirmation page.
            return HttpResponseRedirect(request.get_full_path())

        # Handle POSTed bulk-edit data.
        if request.method == "POST" and cl.list_editable and "_save" in request.POST:
            if not self.has_change_permission(request):
                raise PermissionDenied
            FormSet = self.get_changelist_formset(request)
            modified_objects = self._get_list_editable_queryset(
                request, FormSet.get_default_prefix()
            )
            cl.formset = self._get_formset_with_permissions(
                request,
                queryset=modified_objects,
                for_save=True,
            )
            if cl.formset.is_valid():
                self._save_formset(request, cl.formset)

                return HttpResponseRedirect(request.get_full_path())

        # Handle GET -- construct a formset for display.
        elif cl.list_editable and self.has_change_permission(request):
            cl.formset = self._get_formset_with_permissions(request, cl.result_list)

        # Build the list of media to be used by the formset.
        if cl.formset:
            media = self.media + cl.formset.media
        else:
            media = self.media

        # Build the action form and populate it with available actions.
        if actions:
            action_form = self.action_form(auto_id=None)
            # RemovedInDjango70Warning: When the deprecation ends, replace:
            # action_form.fields["action"].choices = self.get_action_choices(
            #     request, action_location=ActionLocation.CHANGE_LIST
            # )
            action_form.fields["action"].choices = (
                self._get_action_choices_with_action_location(
                    request, action_location=ActionLocation.CHANGE_LIST
                )
            )
            media += action_form.media
        else:
            action_form = None

        selection_note_all = ngettext(
            "%(total_count)s selected", "All %(total_count)s selected", cl.result_count
        )

        context = {
            **self.admin_site.each_context(request),
            "module_name": str(self.opts.verbose_name_plural),
            "selection_note": _("0 of %(cnt)s selected") % {"cnt": len(cl.result_list)},
            "selection_note_all": selection_note_all % {"total_count": cl.result_count},
            "title": cl.title,
            "subtitle": None,
            "is_popup": cl.is_popup,
            "to_field": cl.to_field,
            "cl": cl,
            "media": media,
            "has_add_permission": self.has_add_permission(request),
            "opts": cl.opts,
            "action_form": action_form,
            "actions_on_top": self.actions_on_top,
            "actions_on_bottom": self.actions_on_bottom,
            "actions_selection_counter": self.actions_selection_counter,
            "preserved_filters": self.get_preserved_filters(request),
            **(extra_context or {}),
        }

        request.current_app = self.admin_site.name

        return TemplateResponse(
            request,
            self.change_list_template
            or [
                "admin/%s/%s/change_list.html" % (app_label, self.opts.model_name),
                "admin/%s/change_list.html" % app_label,
                "admin/change_list.html",
            ],
            context,
        )

    def get_deleted_objects(self, objs, request):
        """
        Hook for customizing the delete process for the delete view and the
        "delete selected" action.
        """
        return get_deleted_objects(objs, request, self.admin_site)

    @csrf_protect_m
    def delete_view(self, request, object_id, extra_context=None):
        if request.method in ("GET", "HEAD", "OPTIONS", "TRACE"):
            return self._delete_view(request, object_id, extra_context)

        with transaction.atomic(using=router.db_for_write(self.model)):
            return self._delete_view(request, object_id, extra_context)

    def _delete_view(self, request, object_id, extra_context):
        "The 'delete' admin view for this model."
        app_label = self.opts.app_label

        to_field = request.POST.get(TO_FIELD_VAR, request.GET.get(TO_FIELD_VAR))
        if to_field and not self.to_field_allowed(request, to_field):
            raise DisallowedModelAdminToField(
                "The field %s cannot be referenced." % to_field
            )

        obj = self.get_object(request, unquote(object_id), to_field)

        if not self.has_delete_permission(request, obj):
            raise PermissionDenied

        if obj is None:
            return self._get_obj_does_not_exist_redirect(request, self.opts, object_id)

        # Populate deleted_objects, a data structure of all related objects
        # that will also be deleted.
        (
            deleted_objects,
            model_count,
            perms_needed,
            protected,
        ) = self.get_deleted_objects([obj], request)

        if request.POST and not protected:  # The user has confirmed the deletion.
            if perms_needed:
                raise PermissionDenied
            obj_display = str(obj)
            attr = str(to_field) if to_field else self.opts.pk.attname
            obj_id = obj.serializable_value(attr)
            self.log_deletions(request, [obj])
            self.delete_model(request, obj)

            return self.response_delete(request, obj_display, obj_id)

        object_name = str(self.opts.verbose_name)

        if perms_needed or protected:
            title = _("Cannot delete %(name)s") % {"name": object_name}
        else:
            title = _("Delete")

        context = {
            **self.admin_site.each_context(request),
            "title": title,
            "subtitle": None,
            "object_name": object_name,
            "object": obj,
            "escaped_object": display_for_value(str(obj), EMPTY_VALUE_STRING),
            "deleted_objects": deleted_objects,
            "delete_confirmation_max_display": self.delete_confirmation_max_display,
            "model_count": dict(model_count).items(),
            "perms_lacking": perms_needed,
            "protected": protected,
            "opts": self.opts,
            "app_label": app_label,
            "preserved_filters": self.get_preserved_filters(request),
            "is_popup": IS_POPUP_VAR in request.POST or IS_POPUP_VAR in request.GET,
            "to_field": to_field,
            **(extra_context or {}),
        }

        return self.render_delete_form(request, context)

    def history_view(self, request, object_id, extra_context=None):
        "The 'history' admin view for this model."
        from django.contrib.admin.models import LogEntry
        from django.contrib.admin.views.main import PAGE_VAR

        # First check if the user can see this history.
        model = self.model
        obj = self.get_object(request, unquote(object_id))
        if not self.has_view_or_change_permission(request, obj):
            raise PermissionDenied

        if obj is None:
            return self._get_obj_does_not_exist_redirect(
                request, model._meta, object_id
            )

        # Then get the history for this object.
        app_label = self.opts.app_label
        action_list = (
            LogEntry.objects.filter(
                object_id=unquote(object_id),
                content_type=get_content_type_for_model(model),
            )
            .select_related("user", "content_type")
            .order_by("action_time")
        )

        paginator = self.get_paginator(request, action_list, 100)
        page_number = request.GET.get(PAGE_VAR, 1)
        page_obj = paginator.get_page(page_number)
        page_range = paginator.get_elided_page_range(page_obj.number)

        context = {
            **self.admin_site.each_context(request),
            "title": _("Change history: %s")
            % display_for_value(str(obj), EMPTY_VALUE_STRING),
            "subtitle": None,
            "action_list": page_obj,
            "page_range": page_range,
            "page_var": PAGE_VAR,
            "pagination_required": paginator.count > 100,
            "module_name": str(capfirst(self.opts.verbose_name_plural)),
            "object": obj,
            "opts": self.opts,
            "preserved_filters": self.get_preserved_filters(request),
            **(extra_context or {}),
        }

        request.current_app = self.admin_site.name

        return TemplateResponse(
            request,
            self.object_history_template
            or [
                "admin/%s/%s/object_history.html" % (app_label, self.opts.model_name),
                "admin/%s/object_history.html" % app_label,
                "admin/object_history.html",
            ],
            context,
        )

    def get_formset_kwargs(self, request, obj, inline, prefix):
        formset_params = {
            "instance": obj,
            "prefix": prefix,
            "queryset": inline.get_queryset(request),
        }
        if request.method == "POST":
            formset_params.update(
                {
                    "data": request.POST.copy(),
                    "files": request.FILES,
                    "save_as_new": "_saveasnew" in request.POST,
                }
            )
        return formset_params

    def _create_formsets(self, request, obj, change):
        "Helper function to generate formsets for add/change_view."
        formsets = []
        inline_instances = []
        prefixes = {}
        get_formsets_args = [request]
        if change:
            get_formsets_args.append(obj)
        for FormSet, inline in self.get_formsets_with_inlines(*get_formsets_args):
            prefix = FormSet.get_default_prefix()
            prefixes[prefix] = prefixes.get(prefix, 0) + 1
            if prefixes[prefix] != 1 or not prefix:
                prefix = "%s-%s" % (prefix, prefixes[prefix])
            formset_params = self.get_formset_kwargs(request, obj, inline, prefix)
            if formset_params.get("save_as_new") and not inline.has_add_permission(
                request, None
            ):
                formset_params["data"] = formset_params["data"].copy()
                formset_params["data"]["%s-TOTAL_FORMS" % prefix] = "0"
                formset_params["data"]["%s-INITIAL_FORMS" % prefix] = "0"
            formset = FormSet(**formset_params)

            def user_deleted_form(request, obj, formset, index, inline):
                """Return whether or not the user deleted the form."""
                return (
                    inline.has_delete_permission(request, obj)
                    and "{}-{}-DELETE".format(formset.prefix, index) in request.POST
                )

            # Bypass validation of each view-only inline form (since the form's
            # data won't be in request.POST), unless the form was deleted.
            if not inline.has_change_permission(request, obj if change else None):
                for index, form in enumerate(formset.initial_forms):
                    if user_deleted_form(request, obj, formset, index, inline):
                        continue
                    form._errors = {}
                    form.cleaned_data = form.initial
            formsets.append(formset)
            inline_instances.append(inline)
        return formsets, inline_instances


class InlineModelAdmin(BaseModelAdmin):
    """
    Options for inline editing of ``model`` instances.

    Provide ``fk_name`` to specify the attribute name of the ``ForeignKey``
    from ``model`` to its parent. This is required if ``model`` has more than
    one ``ForeignKey`` to its parent.
    """

    model = None
    fk_name = None
    formset = BaseInlineFormSet
    extra = 3
    min_num = None
    max_num = None
    template = None
    verbose_name = None
    verbose_name_plural = None
    can_delete = True
    show_change_link = False
    checks_class = InlineModelAdminChecks
    classes = None

    def __init__(self, parent_model, admin_site):
        self.admin_site = admin_site
        self.parent_model = parent_model
        self.opts = self.model._meta
        self.has_registered_model = admin_site.is_registered(self.model)
        super().__init__()
        if self.verbose_name_plural is None:
            if self.verbose_name is None:
                self.verbose_name_plural = self.opts.verbose_name_plural
            else:
                self.verbose_name_plural = format_lazy("{}s", self.verbose_name)
        if self.verbose_name is None:
            self.verbose_name = self.opts.verbose_name

    @property
    def media(self):
        extra = "" if settings.DEBUG else ".min"
        js = ["vendor/jquery/jquery%s.js" % extra, "jquery.init.js", "inlines.js"]
        if self.filter_vertical or self.filter_horizontal:
            js.extend(["SelectBox.js", "SelectFilter2.js"])
        return forms.Media(js=["admin/js/%s" % url for url in js])

    def get_extra(self, request, obj=None, **kwargs):
        """Hook for customizing the number of extra inline forms."""
        return self.extra

    def get_min_num(self, request, obj=None, **kwargs):
        """Hook for customizing the min number of inline forms."""
        return self.min_num

    def get_max_num(self, request, obj=None, **kwargs):
        """Hook for customizing the max number of extra inline forms."""
        return self.max_num

    def get_formset(self, request, obj=None, **kwargs):
        """Return a BaseInlineFormSet class for use in add/change views."""
        if "fields" in kwargs:
            fields = kwargs.pop("fields")
        else:
            fields = flatten_fieldsets(self.get_fieldsets(request, obj))
        excluded = self.get_exclude(request, obj)
        exclude = [] if excluded is None else list(excluded)
        exclude.extend(self.get_readonly_fields(request, obj))
        if excluded is None and hasattr(self.form, "_meta") and self.form._meta.exclude:
            # Take the custom ModelForm's Meta.exclude into account only if the
            # InlineModelAdmin doesn't define its own.
            exclude.extend(self.form._meta.exclude)
        # If exclude is an empty list we use None, since that's the actual
        # default.
        exclude = exclude or None
        can_delete = self.can_delete and self.has_delete_permission(request, obj)
        defaults = {
            "form": self.form,
            "formset": self.formset,
            "fk_name": self.fk_name,
            "fields": fields,
            "exclude": exclude,
            "formfield_callback": partial(self.formfield_for_dbfield, request=request),
            "extra": self.get_extra(request, obj, **kwargs),
            "min_num": self.get_min_num(request, obj, **kwargs),
            "max_num": self.get_max_num(request, obj, **kwargs),
            "can_delete": can_delete,
            **kwargs,
        }

        base_model_form = defaults["form"]
        can_change = self.has_change_permission(request, obj) if request else True
        can_add = self.has_add_permission(request, obj) if request else True
        delete_confirmation_max_display = (
            self.delete_confirmation_max_display
            if self.delete_confirmation_max_display
            else sys.maxsize
        )

        class DeleteProtectedModelForm(base_model_form):
            def hand_clean_DELETE(self):
                """
                We don't validate the 'DELETE' field itself because on
                templates it's not rendered using the field information, but
                just using a generic "deletion_field" of the InlineModelAdmin.
                """
                if self.cleaned_data.get(DELETION_FIELD_NAME, False):
                    using = router.db_for_write(self._meta.model)
                    collector = NestedObjects(using=using)
                    if self.instance._state.adding:
                        return
                    collector.collect([self.instance])
                    if collector.protected:
                        objs = []
                        protected = itertools.islice(
                            collector.protected, delete_confirmation_max_display
                        )
                        for p in protected:
                            objs.append(
                                # Translators: Model verbose name and instance
                                # representation, suitable to be an item in a
                                # list.
                                _("%(class_name)s %(instance)s")
                                % {"class_name": p._meta.verbose_name, "instance": p}
                            )
                        params = {
                            "class_name": self._meta.model._meta.verbose_name,
                            "instance": self.instance,
                        }
                        remaining_object_count = (
                            len(collector.protected) - delete_confirmation_max_display
                        )
                        if remaining_object_count > 0:
                            related = (
                                # Translators: This string is used as a
                                # separator between list elements.
                                _(", ").join(str(i) for i in objs)
                                + _(", ")
                                + ngettext(
                                    "…and %(count)d more object.",
                                    "…and %(count)d more objects.",
                                    remaining_object_count,
                                )
                                % {"count": remaining_object_count}
                            )
                        else:
                            related = get_text_list(objs, _("and"))
                        params["related_objects"] = related
                        msg = _(
                            "Deleting %(class_name)s %(instance)s would require "
                            "deleting the following protected related objects: "
                            "%(related_objects)s"
                        )
                        raise ValidationError(
                            msg, code="deleting_protected", params=params
                        )

            def is_valid(self):
                result = super().is_valid()
                self.hand_clean_DELETE()
                return result

            def has_changed(self):
                # Protect against unauthorized edits.
                if not can_change and not self.instance._state.adding:
                    return False
                if not can_add and self.instance._state.adding:
                    return False
                return super().has_changed()

        defaults["form"] = DeleteProtectedModelForm

        if defaults["fields"] is None and not modelform_defines_fields(
            defaults["form"]
        ):
            defaults["fields"] = forms.ALL_FIELDS

        return inlineformset_factory(self.parent_model, self.model, **defaults)

    def _get_form_for_get_fields(self, request, obj=None):
        return self.get_formset(request, obj, fields=None).form

    def get_queryset(self, request):
        queryset = super().get_queryset(request)
        if not self.has_view_or_change_permission(request):
            queryset = queryset.none()
        return queryset

    def _has_any_perms_for_target_model(self, request, perms):
        """
        This method is called only when the ModelAdmin's model is for an
        ManyToManyField's implicit through model (if self.opts.auto_created).
        Return True if the user has any of the given permissions ('add',
        'change', etc.) for the model that points to the through model.
        """
        opts = self.opts
        # Find the target model of an auto-created many-to-many relationship.
        for field in opts.fields:
            if field.remote_field and field.remote_field.model != self.parent_model:
                opts = field.remote_field.model._meta
                break
        return any(
            request.user.has_perm(
                "%s.%s" % (opts.app_label, get_permission_codename(perm, opts))
            )
            for perm in perms
        )

    def has_add_permission(self, request, obj):
        if self.opts.auto_created:
            # Auto-created intermediate models don't have their own
            # permissions. The user needs to have the change permission for the
            # related model in order to be able to do anything with the
            # intermediate model.
            return self._has_any_perms_for_target_model(request, ["change"])
        return super().has_add_permission(request)

    def has_change_permission(self, request, obj=None):
        if self.opts.auto_created:
            # Same comment as has_add_permission().
            return self._has_any_perms_for_target_model(request, ["change"])
        return super().has_change_permission(request)

    def has_delete_permission(self, request, obj=None):
        if self.opts.auto_created:
            # Same comment as has_add_permission().
            return self._has_any_perms_for_target_model(request, ["change"])
        return super().has_delete_permission(request, obj)

    def has_view_permission(self, request, obj=None):
        if self.opts.auto_created:
            # Same comment as has_add_permission(). The 'change' permission
            # also implies the 'view' permission.
            return self._has_any_perms_for_target_model(request, ["view", "change"])
        return super().has_view_permission(request)


class StackedInline(InlineModelAdmin):
    template = "admin/edit_inline/stacked.html"


class TabularInline(InlineModelAdmin):
    template = "admin/edit_inline/tabular.html"

from functools import update_wrapper
from weakref import WeakSet

from django.apps import apps
from django.conf import settings
from django.contrib.admin import ModelAdmin, actions
from django.contrib.admin.exceptions import AlreadyRegistered, NotRegistered
from django.contrib.admin.options import EMPTY_VALUE_STRING
from django.contrib.admin.views.autocomplete import AutocompleteJsonView
from django.contrib.auth import REDIRECT_FIELD_NAME
from django.contrib.auth.decorators import login_not_required
from django.core.exceptions import ImproperlyConfigured, PermissionDenied
from django.db.models.base import ModelBase
from django.http import Http404, HttpResponsePermanentRedirect, HttpResponseRedirect
from django.template.response import TemplateResponse
from django.urls import NoReverseMatch, Resolver404, resolve, reverse, reverse_lazy
from django.utils.decorators import method_decorator
from django.utils.functional import LazyObject
from django.utils.module_loading import import_string
from django.utils.text import capfirst
from django.utils.translation import gettext as _
from django.utils.translation import gettext_lazy
from django.views.decorators.cache import never_cache
from django.views.decorators.common import no_append_slash
from django.views.decorators.csrf import csrf_protect
from django.views.i18n import JavaScriptCatalog

all_sites = WeakSet()


class AdminSite:
    """
    An AdminSite object encapsulates an instance of the Django admin
    application, ready to be hooked in to your URLconf. Models are registered
    with the AdminSite using the register() method, and the get_urls() method
    can then be used to access Django view functions that present a full admin
    interface for the collection of registered models.
    """

    # Text to put at the end of each page's <title>.
    site_title = gettext_lazy("Django site admin")

    # Text to put in each page's <div id="site-name">.
    site_header = gettext_lazy("Django administration")

    # Text to put at the top of the admin index page.
    index_title = gettext_lazy("Site administration")

    # URL for the "View site" link at the top of each admin page.
    site_url = "/"

    enable_nav_sidebar = True

    empty_value_display = EMPTY_VALUE_STRING

    login_form = None
    index_template = None
    app_index_template = None
    login_template = None
    logout_template = None
    password_change_form = None
    password_change_template = None
    password_change_done_template = None

    final_catch_all_view = True

    def __init__(self, name="admin"):
        self._registry = {}  # model_class class -> admin_class instance
        self.name = name
        self._actions = {"delete_selected": actions.delete_selected}
        self._global_actions = self._actions.copy()
        all_sites.add(self)

    def __repr__(self):
        return f"{self.__class__.__name__}(name={self.name!r})"

    def check(self, app_configs):
        """
        Run the system checks on all ModelAdmins, except if they aren't
        customized at all.
        """
        if app_configs is None:
            app_configs = apps.get_app_configs()
        app_configs = set(app_configs)  # Speed up lookups below

        errors = []
        modeladmins = (
            o for o in self._registry.values() if o.__class__ is not ModelAdmin
        )
        for modeladmin in modeladmins:
            if modeladmin.model._meta.app_config in app_configs:
                errors.extend(modeladmin.check())
        return errors

    def register(self, model_or_iterable, admin_class=None, **options):
        """
        Register the given model(s) with the given admin class.

        The model(s) should be Model classes, not instances.

        If an admin class isn't given, use ModelAdmin (the default admin
        options). If keyword arguments are given -- e.g., list_display --
        apply them as options to the admin class.

        If a model is already registered, raise AlreadyRegistered.

        If a model is abstract, raise ImproperlyConfigured.
        """
        admin_class = admin_class or ModelAdmin
        if isinstance(model_or_iterable, ModelBase):
            model_or_iterable = [model_or_iterable]
        for model in model_or_iterable:
            if model._meta.abstract:
                raise ImproperlyConfigured(
                    "The model %s is abstract, so it cannot be registered with admin."
                    % model.__name__
                )
            if model._meta.is_composite_pk:
                raise ImproperlyConfigured(
                    "The model %s has a composite primary key, so it cannot be "
                    "registered with admin." % model.__name__
                )

            if self.is_registered(model):
                registered_admin = str(self.get_model_admin(model))
                msg = "The model %s is already registered " % model.__name__
                if registered_admin.endswith(".ModelAdmin"):
                    # Most likely registered without a ModelAdmin subclass.
                    msg += "in app %r." % registered_admin.removesuffix(".ModelAdmin")
                else:
                    msg += "with %r." % registered_admin
                raise AlreadyRegistered(msg)

            # Ignore the registration if the model has been
            # swapped out.
            if not model._meta.swapped:
                # If we got **options then dynamically construct a subclass of
                # admin_class with those **options.
                if options:
                    # For reasons I don't quite understand, without a
                    # __module__ the created class appears to "live" in the
                    # wrong place, which causes issues later on.
                    options["__module__"] = __name__
                    admin_class = type(
                        "%sAdmin" % model.__name__, (admin_class,), options
                    )

                # Instantiate the admin class to save in the registry
                self._registry[model] = admin_class(model, self)

    def unregister(self, model_or_iterable):
        """
        Unregister the given model(s).

        If a model isn't already registered, raise NotRegistered.
        """
        if isinstance(model_or_iterable, ModelBase):
            model_or_iterable = [model_or_iterable]
        for model in model_or_iterable:
            if not self.is_registered(model):
                raise NotRegistered("The model %s is not registered" % model.__name__)
            del self._registry[model]

    def is_registered(self, model):
        """
        Check if a model class is registered with this `AdminSite`.
        """
        return model in self._registry

    def get_model_admin(self, model):
        try:
            return self._registry[model]
        except KeyError:
            raise NotRegistered(f"The model {model.__name__} is not registered.")

    def add_action(self, action, name=None):
        """
        Register an action to be available globally.
        """
        name = name or action.__name__
        self._actions[name] = action
        self._global_actions[name] = action

    def disable_action(self, name):
        """
        Disable a globally-registered action. Raise KeyError for invalid names.
        """
        del self._actions[name]

    def get_action(self, name):
        """
        Explicitly get a registered global action whether it's enabled or
        not. Raise KeyError for invalid names.
        """
        return self._global_actions[name]

    @property
    def actions(self):
        """
        Get all the enabled actions as an iterable of (name, func).
        """
        return self._actions.items()

    def has_permission(self, request):
        """
        Return True if the given HttpRequest has permission to view
        *at least one* page in the admin site.
        """
        return request.user.is_active and request.user.is_staff

    def admin_view(self, view, cacheable=False):
        """
        Decorator to create an admin view attached to this ``AdminSite``. This
        wraps the view and provides permission checking by calling
        ``self.has_permission``.

        You'll want to use this from within ``AdminSite.get_urls()``:

            class MyAdminSite(AdminSite):

                def get_urls(self):
                    from django.urls import path

                    urls = super().get_urls()
                    urls += [
                        path('my_view/', self.admin_view(some_view))
                    ]
                    return urls

        By default, admin_views are marked non-cacheable using the
        ``never_cache`` decorator. If the view can be safely cached, set
        cacheable=True.
        """

        def inner(request, *args, **kwargs):
            if not self.has_permission(request):
                if request.path == reverse("admin:logout", current_app=self.name):
                    index_path = reverse("admin:index", current_app=self.name)
                    return HttpResponseRedirect(index_path)
                # Inner import to prevent django.contrib.admin (app) from
                # importing django.contrib.auth.models.User (unrelated model).
                from django.contrib.auth.views import redirect_to_login

                return redirect_to_login(
                    request.get_full_path(),
                    reverse("admin:login", current_app=self.name),
                )
            return view(request, *args, **kwargs)

        if not cacheable:
            inner = never_cache(inner)
        # We add csrf_protect here so this function can be used as a utility
        # function for any view, without having to repeat 'csrf_protect'.
        if not getattr(view, "csrf_exempt", False):
            inner = csrf_protect(inner)
        return update_wrapper(inner, view)

    def get_urls(self):
        from django.urls import include, path, re_path

        def wrap(view, cacheable=False):
            def wrapper(*args, **kwargs):
                return self.admin_view(view, cacheable)(*args, **kwargs)

            wrapper.admin_site = self
            # Used by LoginRequiredMiddleware.
            wrapper.login_url = reverse_lazy("admin:login", current_app=self.name)
            return update_wrapper(wrapper, view)

        # Admin-site-wide views.
        urlpatterns = [
            path("", wrap(self.index), name="index"),
            path("login/", self.login, name="login"),
            path("logout/", wrap(self.logout), name="logout"),
            path(
                "password_change/",
                wrap(self.password_change, cacheable=True),
                name="password_change",
            ),
            path(
                "password_change/done/",
                wrap(self.password_change_done, cacheable=True),
                name="password_change_done",
            ),
            path("autocomplete/", wrap(self.autocomplete_view), name="autocomplete"),
            path("jsi18n/", wrap(self.i18n_javascript, cacheable=True), name="jsi18n"),
            path(
                "r/<path:content_type_id>/<path:object_id>/",
                wrap(self.shortcut_view),
                name="view_on_site",
            ),
        ]

        # Add in each model's views, and create a list of valid URLS for the
        # app_index
        valid_app_labels = []
        for model, model_admin in self._registry.items():
            urlpatterns += [
                path(
                    "%s/%s/" % (model._meta.app_label, model._meta.model_name),
                    include(model_admin.urls),
                ),
            ]
            if model._meta.app_label not in valid_app_labels:
                valid_app_labels.append(model._meta.app_label)

        # If there were ModelAdmins registered, we should have a list of app
        # labels for which we need to allow access to the app_index view,
        if valid_app_labels:
            regex = r"^(?P<app_label>" + "|".join(valid_app_labels) + ")/$"
            urlpatterns += [
                re_path(regex, wrap(self.app_index), name="app_list"),
            ]

        if self.final_catch_all_view:
            urlpatterns.append(re_path(r"(?P<url>.*)$", wrap(self.catch_all_view)))

        return urlpatterns

    @property
    def urls(self):
        return self.get_urls(), "admin", self.name

    def each_context(self, request):
        """
        Return a dictionary of variables to put in the template context for
        *every* page in the admin site.

        For sites running on a subpath, use the SCRIPT_NAME value if site_url
        hasn't been customized.
        """
        script_name = request.META["SCRIPT_NAME"]
        site_url = (
            script_name if self.site_url == "/" and script_name else self.site_url
        )
        return {
            "site_title": self.site_title,
            "site_header": self.site_header,
            "site_url": site_url,
            "has_permission": self.has_permission(request),
            "available_apps": self.get_app_list(request),
            "is_popup": False,
            "is_nav_sidebar_enabled": self.enable_nav_sidebar,
            "log_entries": self.get_log_entries(request),
        }

    def password_change(self, request, extra_context=None):
        """
        Handle the "change password" task -- both form display and validation.
        """
        from django.contrib.admin.forms import AdminPasswordChangeForm
        from django.contrib.auth.views import PasswordChangeView

        url = reverse("admin:password_change_done", current_app=self.name)
        defaults = {
            "form_class": self.password_change_form or AdminPasswordChangeForm,
            "success_url": url,
            "extra_context": {**self.each_context(request), **(extra_context or {})},
        }
        if self.password_change_template is not None:
            defaults["template_name"] = self.password_change_template
        request.current_app = self.name
        return PasswordChangeView.as_view(**defaults)(request)

    def password_change_done(self, request, extra_context=None):
        """
        Display the "success" page after a password change.
        """
        from django.contrib.auth.views import PasswordChangeDoneView

        defaults = {
            "extra_context": {**self.each_context(request), **(extra_context or {})},
        }
        if self.password_change_done_template is not None:
            defaults["template_name"] = self.password_change_done_template
        request.current_app = self.name
        return PasswordChangeDoneView.as_view(**defaults)(request)

    def i18n_javascript(self, request, extra_context=None):
        """
        Display the i18n JavaScript that the Django admin requires.

        `extra_context` is unused but present for consistency with the other
        admin views.
        """
        return JavaScriptCatalog.as_view(packages=["django.contrib.admin"])(request)

    def logout(self, request, extra_context=None):
        """
        Log out the user for the given HttpRequest.

        This should *not* assume the user is already logged in.
        """
        from django.contrib.auth.views import LogoutView

        defaults = {
            "extra_context": {
                **self.each_context(request),
                # Since the user isn't logged out at this point, the value of
                # has_permission must be overridden.
                "has_permission": False,
                **(extra_context or {}),
            },
        }
        if self.logout_template is not None:
            defaults["template_name"] = self.logout_template
        request.current_app = self.name
        return LogoutView.as_view(**defaults)(request)

    @method_decorator(never_cache)
    @login_not_required
    def login(self, request, extra_context=None):
        """
        Display the login form for the given HttpRequest.
        """
        # Since this module gets imported in the application's root package,
        # it cannot import models from other applications at the module level,
        # and django.contrib.admin.forms eventually imports User.
        from django.contrib.admin.forms import AdminAuthenticationForm
        from django.contrib.auth.views import LoginView

        redirect_url = LoginView().get_redirect_url(request) or reverse(
            "admin:index", current_app=self.name
        )
        if request.method == "GET" and self.has_permission(request):
            # Already logged-in, redirect accordingly.
            return HttpResponseRedirect(redirect_url)

        context = {
            **self.each_context(request),
            "title": _("Log in"),
            "subtitle": None,
            "app_path": request.get_full_path(),
            "username": request.user.get_username(),
            REDIRECT_FIELD_NAME: redirect_url,
        }
        context.update(extra_context or {})

        defaults = {
            "extra_context": context,
            "authentication_form": self.login_form or AdminAuthenticationForm,
            "template_name": self.login_template or "admin/login.html",
        }
        request.current_app = self.name
        return LoginView.as_view(**defaults)(request)

    def autocomplete_view(self, request):
        return AutocompleteJsonView.as_view(admin_site=self)(request)

    def shortcut_view(self, request, content_type_id, object_id):
        from django.contrib.contenttypes import views as contenttype_views
        from django.contrib.contenttypes.models import ContentType

        try:
            content_type = ContentType.objects.get_for_id(int(content_type_id))
        except (ContentType.DoesNotExist, ValueError):
            pass
        else:
            model_class = content_type.model_class()
            if (
                model_class is not None
                and self.is_registered(model_class)
                and not self.get_model_admin(model_class).has_view_permission(request)
            ):
                raise PermissionDenied
        return contenttype_views.shortcut(request, content_type_id, object_id)

    @no_append_slash
    def catch_all_view(self, request, url):
        if settings.APPEND_SLASH and not url.endswith("/"):
            urlconf = getattr(request, "urlconf", None)
            try:
                match = resolve("%s/" % request.path_info, urlconf)
            except Resolver404:
                pass
            else:
                if getattr(match.func, "should_append_slash", True):
                    return HttpResponsePermanentRedirect(
                        request.get_full_path(force_append_slash=True)
                    )
        raise Http404

    def _build_app_dict(self, request, label=None):
        """
        Build the app dictionary. The optional `label` parameter filters models
        of a specific app.
        """
        app_dict = {}

        if label:
            models = {
                m: m_a
                for m, m_a in self._registry.items()
                if m._meta.app_label == label
            }
        else:
            models = self._registry

        for model, model_admin in models.items():
            app_label = model._meta.app_label

            has_module_perms = model_admin.has_module_permission(request)
            if not has_module_perms:
                continue

            perms = model_admin.get_model_perms(request)

            # Check whether user has any perm for this module.
            # If so, add the module to the model_list.
            if True not in perms.values():
                continue

            info = (app_label, model._meta.model_name)
            model_dict = {
                "model": model,
                "name": capfirst(model._meta.verbose_name_plural),
                "object_name": model._meta.object_name,
                "perms": perms,
                "admin_url": None,
                "add_url": None,
            }
            if perms.get("change") or perms.get("view"):
                model_dict["view_only"] = not perms.get("change")
                try:
                    model_dict["admin_url"] = reverse(
                        "admin:%s_%s_changelist" % info, current_app=self.name
                    )
                except NoReverseMatch:
                    pass
            if perms.get("add"):
                try:
                    model_dict["add_url"] = reverse(
                        "admin:%s_%s_add" % info, current_app=self.name
                    )
                except NoReverseMatch:
                    pass

            if app_label in app_dict:
                app_dict[app_label]["models"].append(model_dict)
            else:
                app_dict[app_label] = {
                    "name": apps.get_app_config(app_label).verbose_name,
                    "app_label": app_label,
                    "app_url": reverse(
                        "admin:app_list",
                        kwargs={"app_label": app_label},
                        current_app=self.name,
                    ),
                    "has_module_perms": has_module_perms,
                    "models": [model_dict],
                }

        return app_dict

    def get_app_list(self, request, app_label=None):
        """
        Return a sorted list of all the installed apps that have been
        registered in this site.
        """
        app_dict = self._build_app_dict(request, app_label)

        # Sort the apps alphabetically.
        app_list = sorted(app_dict.values(), key=lambda x: x["name"].lower())

        # Sort the models alphabetically within each app.
        for app in app_list:
            app["models"].sort(key=lambda x: x["name"])

        return app_list

    def index(self, request, extra_context=None):
        """
        Display the main admin index page, which lists all of the installed
        apps that have been registered in this site.
        """
        app_list = self.get_app_list(request)

        context = {
            **self.each_context(request),
            "title": self.index_title,
            "subtitle": None,
            "app_list": app_list,
            **(extra_context or {}),
        }

        request.current_app = self.name

        return TemplateResponse(
            request, self.index_template or "admin/index.html", context
        )

    def app_index(self, request, app_label, extra_context=None):
        app_list = self.get_app_list(request, app_label)

        if not app_list:
            raise Http404("The requested admin page does not exist.")

        context = {
            **self.each_context(request),
            "title": _("%(app)s administration") % {"app": app_list[0]["name"]},
            "subtitle": None,
            "app_list": app_list,
            "app_label": app_label,
            **(extra_context or {}),
        }

        request.current_app = self.name

        return TemplateResponse(
            request,
            self.app_index_template
            or ["admin/%s/app_index.html" % app_label, "admin/app_index.html"],
            context,
        )

    def get_log_entries(self, request):
        from django.contrib.admin.models import LogEntry

        return LogEntry.objects.select_related("content_type", "user")


class DefaultAdminSite(LazyObject):
    def _setup(self):
        AdminSiteClass = import_string(apps.get_app_config("admin").default_site)
        self._wrapped = AdminSiteClass()

    def __repr__(self):
        return repr(self._wrapped)


# This global object represents the default admin site, for the common case.
# You can provide your own AdminSite using the (Simple)AdminConfig.default_site
# attribute. You can also instantiate AdminSite in your own code to create a
# custom admin site.
site = DefaultAdminSite()

/*global gettext, interpolate, ngettext, Actions*/
"use strict";
{
    function show(selector) {
        document.querySelectorAll(selector).forEach(function (el) {
            el.classList.remove("hidden");
        });
    }

    function hide(selector) {
        document.querySelectorAll(selector).forEach(function (el) {
            el.classList.add("hidden");
        });
    }

    function showQuestion(options) {
        hide(options.acrossClears);
        show(options.acrossQuestions);
        hide(options.allContainer);
    }

    function showClear(options) {
        show(options.acrossClears);
        hide(options.acrossQuestions);
        document
            .querySelector(options.actionContainer)
            .classList.remove(options.selectedClass);
        show(options.allContainer);
        hide(options.counterContainer);
    }

    function reset(options) {
        hide(options.acrossClears);
        hide(options.acrossQuestions);
        hide(options.allContainer);
        show(options.counterContainer);
    }

    function clearAcross(options) {
        reset(options);
        const acrossInputs = document.querySelectorAll(options.acrossInput);
        acrossInputs.forEach(function (acrossInput) {
            acrossInput.value = 0;
        });
        document
            .querySelector(options.actionContainer)
            .classList.remove(options.selectedClass);
    }

    function checker(actionCheckboxes, options, checked) {
        if (checked) {
            showQuestion(options);
        } else {
            reset(options);
        }
        actionCheckboxes.forEach(function (el) {
            el.checked = checked;
            el.closest("tr").classList.toggle(options.selectedClass, checked);
        });
    }

    function updateCounter(actionCheckboxes, options) {
        const sel = Array.from(actionCheckboxes).filter(function (el) {
            return el.checked;
        }).length;
        const counter = document.querySelector(options.counterContainer);
        // data-actions-icnt is defined in the generated HTML
        // and contains the total amount of objects in the queryset
        const actions_icnt = Number(counter.dataset.actionsIcnt);
        counter.textContent = interpolate(
            ngettext(
                "%(sel)s of %(cnt)s selected",
                "%(sel)s of %(cnt)s selected",
                sel,
            ),
            {
                sel: sel,
                cnt: actions_icnt,
            },
            true,
        );
        const allToggle = document.getElementById(options.allToggleId);
        allToggle.checked = sel === actionCheckboxes.length;
        if (allToggle.checked) {
            showQuestion(options);
        } else {
            clearAcross(options);
        }
    }

    const defaults = {
        actionContainer: "div.actions",
        counterContainer: "span.action-counter",
        allContainer: "div.actions span.all",
        acrossInput: "div.actions input.select-across",
        acrossQuestions: "div.actions span.question",
        acrossClears: "div.actions span.clear",
        allToggleId: "action-toggle",
        selectedClass: "selected",
    };

    window.Actions = function (actionCheckboxes, options) {
        options = Object.assign({}, defaults, options);
        let list_editable_changed = false;
        let lastChecked = null;
        let shiftPressed = false;

        document.addEventListener("keydown", (event) => {
            shiftPressed = event.shiftKey;
        });

        document.addEventListener("keyup", (event) => {
            shiftPressed = event.shiftKey;
        });

        document
            .getElementById(options.allToggleId)
            .addEventListener("click", function (event) {
                checker(actionCheckboxes, options, this.checked);
                updateCounter(actionCheckboxes, options);
            });

        document
            .querySelectorAll(options.acrossQuestions + " a")
            .forEach(function (el) {
                el.addEventListener("click", function (event) {
                    event.preventDefault();
                    const acrossInputs = document.querySelectorAll(
                        options.acrossInput,
                    );
                    acrossInputs.forEach(function (acrossInput) {
                        acrossInput.value = 1;
                    });
                    showClear(options);
                });
            });

        document
            .querySelectorAll(options.acrossClears + " a")
            .forEach(function (el) {
                el.addEventListener("click", function (event) {
                    event.preventDefault();
                    document.getElementById(options.allToggleId).checked =
                        false;
                    clearAcross(options);
                    checker(actionCheckboxes, options, false);
                    updateCounter(actionCheckboxes, options);
                });
            });

        function affectedCheckboxes(target, withModifier) {
            const multiSelect =
                lastChecked && withModifier && lastChecked !== target;
            if (!multiSelect) {
                return [target];
            }
            const checkboxes = Array.from(actionCheckboxes);
            const targetIndex = checkboxes.findIndex((el) => el === target);
            const lastCheckedIndex = checkboxes.findIndex(
                (el) => el === lastChecked,
            );
            const startIndex = Math.min(targetIndex, lastCheckedIndex);
            const endIndex = Math.max(targetIndex, lastCheckedIndex);
            const filtered = checkboxes.filter(
                (el, index) => startIndex <= index && index <= endIndex,
            );
            return filtered;
        }

        Array.from(document.getElementById("result_list").tBodies).forEach(
            function (el) {
                el.addEventListener("change", function (event) {
                    const target = event.target;
                    if (target.classList.contains("action-select")) {
                        const checkboxes = affectedCheckboxes(
                            target,
                            shiftPressed,
                        );
                        checker(checkboxes, options, target.checked);
                        updateCounter(actionCheckboxes, options);
                        lastChecked = target;
                    } else {
                        list_editable_changed = true;
                    }
                });
            },
        );

        document
            .querySelector("#changelist-form button[name=index]")
            .addEventListener("click", function (event) {
                if (list_editable_changed) {
                    const confirmed = confirm(
                        gettext(
                            "You have unsaved changes on individual editable fields. If you run an action, your unsaved changes will be lost.",
                        ),
                    );
                    if (!confirmed) {
                        event.preventDefault();
                    }
                }
            });

        const el = document.querySelector("#changelist-form input[name=_save]");
        // The button does not exist if no fields are editable.
        if (el) {
            el.addEventListener("click", function (event) {
                if (document.querySelector("[name=action]").value) {
                    const text = list_editable_changed
                        ? gettext(
                              "You have selected an action, but you haven’t saved your changes to individual fields yet. Please click OK to save. You’ll need to re-run the action.",
                          )
                        : gettext(
                              "You have selected an action, and you haven’t made any changes on individual fields. You’re probably looking for the Run button rather than the Save button.",
                          );
                    if (!confirm(text)) {
                        event.preventDefault();
                    }
                }
            });
        }
        // Sync counter when navigating to the page, such as through the back
        // button.
        window.addEventListener("pageshow", (event) =>
            updateCounter(actionCheckboxes, options),
        );
    };

    // Call function fn when the DOM is loaded and ready. If it is already
    // loaded, call the function now.
    // http://youmightnotneedjquery.com/#ready
    function ready(fn) {
        if (document.readyState !== "loading") {
            fn();
        } else {
            document.addEventListener("DOMContentLoaded", fn);
        }
    }

    ready(function () {
        const actionsEls = document.querySelectorAll("tr input.action-select");
        if (actionsEls.length > 0) {
            Actions(actionsEls);
        }
    });
}

/*global Calendar, CalendarNamespace, findPosX, findPosY, get_format, gettext, gettext_noop, interpolate, ngettext, quickElement*/
// Inserts shortcut buttons after all of the following:
//     <input type="text" class="vDateField">
//     <input type="text" class="vTimeField">
"use strict";
{
    const DateTimeShortcuts = {
        calendars: [],
        calendarInputs: [],
        clockInputs: [],
        clockHours: {
            default_: [
                [gettext_noop("Now"), -1],
                [gettext_noop("Midnight"), 0],
                [gettext_noop("6 a.m."), 6],
                [gettext_noop("Noon"), 12],
                [gettext_noop("6 p.m."), 18],
            ],
        },
        dismissClockFunc: [],
        dismissCalendarFunc: [],
        calendarDivName1: "calendarbox", // name of calendar <div> that gets toggled
        calendarDivName2: "calendarin", // name of <div> that contains calendar
        calendarLinkName: "calendarlink", // name of the link that is used to toggle
        clockDivName: "clockbox", // name of clock <div> that gets toggled
        clockLinkName: "clocklink", // name of the link that is used to toggle
        shortCutsClass: "datetimeshortcuts", // class of the clock and cal shortcuts
        timezoneWarningClass: "timezonewarning", // class of the warning for timezone mismatch
        timezoneOffset: 0,
        init: function () {
            const serverOffset = document.body.dataset.adminUtcOffset;
            if (serverOffset) {
                const localOffset = new Date().getTimezoneOffset() * -60;
                DateTimeShortcuts.timezoneOffset = localOffset - serverOffset;
            }

            for (const inp of document.getElementsByTagName("input")) {
                if (
                    inp.type === "text" &&
                    inp.classList.contains("vTimeField")
                ) {
                    DateTimeShortcuts.addClock(inp);
                    DateTimeShortcuts.addTimezoneWarning(inp);
                } else if (
                    inp.type === "text" &&
                    inp.classList.contains("vDateField")
                ) {
                    DateTimeShortcuts.addCalendar(inp);
                    DateTimeShortcuts.addTimezoneWarning(inp);
                }
            }
        },
        // Return the current time while accounting for the server timezone.
        now: function () {
            return CalendarNamespace.serverToday();
        },
        // Add a warning when the time zone in the browser and backend do not match.
        addTimezoneWarning: function (inp) {
            const warningClass = DateTimeShortcuts.timezoneWarningClass;
            let timezoneOffset = DateTimeShortcuts.timezoneOffset / 3600;

            // Only warn if there is a time zone mismatch.
            if (!timezoneOffset) {
                return;
            }

            // Check if warning is already there.
            if (
                inp.parentNode.parentNode.querySelectorAll("." + warningClass)
                    .length
            ) {
                return;
            }

            const serverTimezone =
                document.body.dataset.adminServerTimezone || gettext("server");
            let message;
            if (timezoneOffset > 0) {
                message = ngettext(
                    "Note: Enter times in the %(timezone)s timezone. " +
                        "(You are %(offset)s hour ahead.)",
                    "Note: Enter times in the %(timezone)s timezone. " +
                        "(You are %(offset)s hours ahead.)",
                    timezoneOffset,
                );
            } else {
                timezoneOffset *= -1;
                message = ngettext(
                    "Note: Enter times in the %(timezone)s timezone. " +
                        "(You are %(offset)s hour behind.)",
                    "Note: Enter times in the %(timezone)s timezone. " +
                        "(You are %(offset)s hours behind.)",
                    timezoneOffset,
                );
            }
            message = interpolate(
                message,
                { timezone: serverTimezone, offset: timezoneOffset },
                true,
            );

            const warning = document.createElement("div");
            const id = inp.id;
            const field_id = inp.closest("p.datetime")
                ? id.slice(0, id.lastIndexOf("_"))
                : id;
            warning.classList.add("help", warningClass);
            warning.id = `${field_id}_timezone_warning_helptext`;
            warning.textContent = message;
            const errorList =
                inp.parentNode.parentNode.querySelector("ul.errorlist");
            if (errorList) {
                errorList.before(warning);
            } else {
                inp.parentNode.before(warning);
            }
        },
        // Add clock widget to a given field
        addClock: function (inp) {
            const num = DateTimeShortcuts.clockInputs.length;
            DateTimeShortcuts.clockInputs[num] = inp;
            DateTimeShortcuts.dismissClockFunc[num] = function () {
                DateTimeShortcuts.dismissClock(num);
                return true;
            };

            // Shortcut links (clock icon and "Now" link)
            const shortcuts_span = document.createElement("span");
            shortcuts_span.className = DateTimeShortcuts.shortCutsClass;
            inp.parentNode.insertBefore(shortcuts_span, inp.nextSibling);
            const now_link = document.createElement("a");
            now_link.href = "#";
            now_link.textContent = gettext("Now");
            now_link.role = "button";
            now_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.handleClockQuicklink(num, -1);
            });
            const clock_link = document.createElement("button");
            clock_link.type = "button";
            clock_link.id = DateTimeShortcuts.clockLinkName + num;
            clock_link.addEventListener("click", function (e) {
                e.preventDefault();
                // avoid triggering the document click handler to dismiss the clock
                e.stopPropagation();
                DateTimeShortcuts.openClock(num);
            });

            const clockIconId = DateTimeShortcuts.clockLinkName + num + "_icon";
            quickElement(
                "span",
                clock_link,
                "",
                "id",
                clockIconId,
                "class",
                "clock-icon",
                "title",
                gettext("Choose a Time"),
            );
            clock_link.setAttribute("aria-labelledby", clockIconId);
            shortcuts_span.appendChild(document.createTextNode("\u00A0"));
            shortcuts_span.appendChild(now_link);
            shortcuts_span.appendChild(
                document.createTextNode("\u00A0|\u00A0"),
            );
            shortcuts_span.appendChild(clock_link);

            // Create clock link div
            //
            // Markup looks like:
            // <dialog id="clockbox1" class="clockbox module" role="dialog"
            //     aria-label="Choose a time">
            //     <h2>Choose a time</h2>
            //     <ul class="timelist">
            //         <li><a href="#" role="button">Now</a></li>
            //         <li><a href="#" role="button">Midnight</a></li>
            //         <li><a href="#" role="button">6 a.m.</a></li>
            //         <li><a href="#" role="button">Noon</a></li>
            //         <li><a href="#" role="button">6 p.m.</a></li>
            //     </ul>
            //     <p class="calendar-cancel">
            //         <a href="#" role="button" aria-label="Close Clock">Cancel</a>
            //     </p>
            // </dialog>

            const clock_box = document.createElement("dialog");
            clock_box.className = "clockbox module";
            clock_box.id = DateTimeShortcuts.clockDivName + num;
            clock_box.setAttribute("role", "dialog");
            clock_box.setAttribute("aria-labelledby", clockIconId);
            document.body.appendChild(clock_box);
            clock_box.addEventListener("click", function (e) {
                e.stopPropagation();
            });

            quickElement("h2", clock_box, gettext("Choose a time"));
            const time_list = quickElement("ul", clock_box);
            time_list.className = "timelist";
            // The list of choices can be overridden in JavaScript like this:
            // DateTimeShortcuts.clockHours.name = [['3 a.m.', 3]];
            // where name is the name attribute of the <input>.
            const name =
                typeof DateTimeShortcuts.clockHours[inp.name] === "undefined"
                    ? "default_"
                    : inp.name;
            DateTimeShortcuts.clockHours[name].forEach(function (element) {
                const time_link = quickElement(
                    "a",
                    quickElement("li", time_list),
                    gettext(element[0]),
                    "role",
                    "button",
                    "href",
                    "#",
                );
                time_link.addEventListener("click", function (e) {
                    e.preventDefault();
                    DateTimeShortcuts.handleClockQuicklink(num, element[1]);
                });
            });

            const cancel_p = quickElement("p", clock_box);
            cancel_p.className = "calendar-cancel";
            const cancel_link = quickElement(
                "a",
                cancel_p,
                gettext("Cancel"),
                "role",
                "button",
                "href",
                "#",
            );
            cancel_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.dismissClock(num);
            });

            document.addEventListener("keyup", function (event) {
                if (event.key === "Escape") {
                    // ESC key closes popup
                    DateTimeShortcuts.dismissClock(num);
                    event.preventDefault();
                }
            });
        },
        openClock: function (num) {
            const clock_box = document.getElementById(
                DateTimeShortcuts.clockDivName + num,
            );
            const clock_link = document.getElementById(
                DateTimeShortcuts.clockLinkName + num,
            );

            // Recalculate the clockbox position
            // is it left-to-right or right-to-left layout ?
            if (window.getComputedStyle(document.body).direction !== "rtl") {
                clock_box.style.left = findPosX(clock_link) + 17 + "px";
            } else {
                // since style's width is in em, it'd be tough to calculate
                // px value of it. let's use an estimated px for now
                clock_box.style.right = findPosX(clock_link) - 110 + "px";
            }
            clock_box.style.top = Math.max(0, findPosY(clock_link) - 30) + "px";

            // Show the clock box
            clock_box.showModal();
        },
        dismissClock: function (num) {
            document
                .getElementById(DateTimeShortcuts.clockDivName + num)
                .close();
        },
        handleClockQuicklink: function (num, val) {
            let d;
            if (val === -1) {
                d = DateTimeShortcuts.now();
            } else {
                d = new Date(1970, 1, 1, val, 0, 0, 0);
            }
            DateTimeShortcuts.clockInputs[num].value = d.strftime(
                get_format("TIME_INPUT_FORMATS")[0],
            );
            DateTimeShortcuts.clockInputs[num].focus();
            DateTimeShortcuts.dismissClock(num);
        },
        // Add calendar widget to a given field.
        addCalendar: function (inp) {
            const num = DateTimeShortcuts.calendars.length;

            DateTimeShortcuts.calendarInputs[num] = inp;
            DateTimeShortcuts.dismissCalendarFunc[num] = function () {
                DateTimeShortcuts.dismissCalendar(num);
                return true;
            };

            function getFormattedDate(offset) {
                const d = DateTimeShortcuts.now();
                d.setDate(d.getDate() + offset);
                return CalendarNamespace.formatDate(
                    d.getDate(),
                    d.getMonth() + 1,
                    d.getFullYear(),
                );
            }
            // Shortcut links (calendar icon and "Today" link)
            const shortcuts_span = document.createElement("span");
            shortcuts_span.className = DateTimeShortcuts.shortCutsClass;
            inp.parentNode.insertBefore(shortcuts_span, inp.nextSibling);
            const today_link = document.createElement("a");
            today_link.href = "#";
            today_link.role = "button";
            today_link.appendChild(document.createTextNode(gettext("Today")));
            today_link.setAttribute(
                "aria-label",
                interpolate(
                    gettext("Today (%(date)s)"),
                    { date: getFormattedDate(0) },
                    true,
                ),
            );
            today_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, 0);
            });
            const cal_link = document.createElement("button");
            cal_link.type = "button";
            cal_link.id = DateTimeShortcuts.calendarLinkName + num;
            cal_link.addEventListener("click", function (e) {
                e.preventDefault();
                // avoid triggering the document click handler to dismiss the calendar
                e.stopPropagation();
                DateTimeShortcuts.openCalendar(num);
            });
            const calIconId =
                DateTimeShortcuts.calendarLinkName + num + "_icon";
            quickElement(
                "span",
                cal_link,
                "",
                "id",
                calIconId,
                "class",
                "date-icon",
                "title",
                gettext("Choose a Date"),
            );
            cal_link.setAttribute("aria-labelledby", calIconId);
            shortcuts_span.appendChild(document.createTextNode("\u00A0"));
            shortcuts_span.appendChild(today_link);
            shortcuts_span.appendChild(
                document.createTextNode("\u00A0|\u00A0"),
            );
            shortcuts_span.appendChild(cal_link);

            // Create calendarbox div.
            //
            // Markup looks like:
            //
            // <dialog id="calendarbox3" class="calendarbox module"
            //      role="dialog" aria-label="Choose a Date">
            //     <div>
            //         <a href="#" class="calendarnav-previous"
            //            aria-label="Previous May">&lsaquo;</a>
            //         <a href="#" class="calendarnav-next"
            //            aria-label="Next July">&rsaquo;</a>
            //     </div>
            //     <div class="calendar" id="calendarin3">
            //         <!-- (cal) -->
            //     </div>
            //     <div class="calendar-shortcuts">
            //         <a href="#" role="button"
            //            aria-label="Yesterday (June 14, 2025)">Yesterday</a>
            //         |
            //         <a href="#" role="button"
            //            aria-label="Today (June 15, 2025)">Today</a>
            //         |
            //         <a href="#" role="button"
            //            aria-label="Tomorrow (June 16, 2025)">Tomorrow</a>
            //     </div>
            //     <p class="calendar-cancel">
            //         <a href="#" role="button" aria-label="Close Calendar">Cancel</a>
            //     </p>
            // </dialog>
            const cal_box = document.createElement("dialog");
            cal_box.className = "calendarbox module";
            cal_box.id = DateTimeShortcuts.calendarDivName1 + num;
            cal_box.setAttribute("role", "dialog");
            cal_box.setAttribute("aria-labelledby", calIconId);
            document.body.appendChild(cal_box);
            cal_box.addEventListener("click", function (e) {
                e.stopPropagation();
            });
            // Handle arrow key navigation within the calendar
            cal_box.addEventListener("keydown", function (event) {
                const focused = cal_box.querySelector("a:focus");
                if (!focused) return;
                const cells = Array.from(cal_box.querySelectorAll("td a"));
                const currentIndex = cells.indexOf(focused);
                if (currentIndex === -1) return;

                const ltr =
                    window.getComputedStyle(document.body).direction !== "rtl";
                const forward = ltr
                    ? event.key === "ArrowRight"
                    : event.key === "ArrowLeft";
                const backward = ltr
                    ? event.key === "ArrowLeft"
                    : event.key === "ArrowRight";
                let nextCell = null;
                const cellsPerRow = 7;

                if (forward && currentIndex < cells.length - 1) {
                    nextCell = cells[currentIndex + 1];
                } else if (backward && currentIndex > 0) {
                    nextCell = cells[currentIndex - 1];
                } else if (
                    event.key === "ArrowDown" &&
                    currentIndex + cellsPerRow < cells.length
                ) {
                    nextCell = cells[currentIndex + cellsPerRow];
                } else if (
                    event.key === "ArrowUp" &&
                    currentIndex - cellsPerRow >= 0
                ) {
                    nextCell = cells[currentIndex - cellsPerRow];
                }

                if (nextCell) {
                    event.preventDefault();
                    nextCell.focus();
                }
            });
            // next-prev links
            const cal_nav = quickElement("div", cal_box);
            const cal_nav_prev = quickElement("a", cal_nav, "<", "href", "#");
            cal_nav_prev.className = "calendarnav-previous";
            cal_nav_prev.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.drawPrev(num);
            });

            const cal_nav_next = quickElement("a", cal_nav, ">", "href", "#");
            cal_nav_next.className = "calendarnav-next";
            cal_nav_next.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.drawNext(num);
            });

            // main box
            const cal_main = quickElement(
                "div",
                cal_box,
                "",
                "id",
                DateTimeShortcuts.calendarDivName2 + num,
            );
            cal_main.className = "calendar";
            DateTimeShortcuts.calendars[num] = new Calendar(
                DateTimeShortcuts.calendarDivName2 + num,
                DateTimeShortcuts.handleCalendarCallback(num),
            );
            DateTimeShortcuts.calendars[num].drawCurrent();

            // calendar shortcuts
            const shortcuts = quickElement("div", cal_box);
            shortcuts.className = "calendar-shortcuts";
            let day_link = quickElement(
                "a",
                shortcuts,
                gettext("Yesterday"),
                "role",
                "button",
                "href",
                "#",
            );
            day_link.setAttribute(
                "aria-label",
                interpolate(
                    gettext("Yesterday (%(date)s)"),
                    { date: getFormattedDate(-1) },
                    true,
                ),
            );
            day_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, -1);
            });
            shortcuts.appendChild(document.createTextNode("\u00A0|\u00A0"));
            day_link = quickElement(
                "a",
                shortcuts,
                gettext("Today"),
                "role",
                "button",
                "href",
                "#",
            );
            day_link.setAttribute(
                "aria-label",
                interpolate(
                    gettext("Today (%(date)s)"),
                    { date: getFormattedDate(0) },
                    true,
                ),
            );
            day_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, 0);
            });
            shortcuts.appendChild(document.createTextNode("\u00A0|\u00A0"));
            day_link = quickElement(
                "a",
                shortcuts,
                gettext("Tomorrow"),
                "role",
                "button",
                "href",
                "#",
            );
            day_link.setAttribute(
                "aria-label",
                interpolate(
                    gettext("Tomorrow (%(date)s)"),
                    { date: getFormattedDate(1) },
                    true,
                ),
            );
            day_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.handleCalendarQuickLink(num, +1);
            });

            // cancel bar
            const cancel_p = quickElement("p", cal_box);
            cancel_p.className = "calendar-cancel";
            const cancel_link = quickElement(
                "a",
                cancel_p,
                gettext("Cancel"),
                "role",
                "button",
                "href",
                "#",
            );
            cancel_link.addEventListener("click", function (e) {
                e.preventDefault();
                DateTimeShortcuts.dismissCalendar(num);
            });
            document.addEventListener("keyup", function (event) {
                if (event.key === "Escape") {
                    // ESC key closes popup
                    DateTimeShortcuts.dismissCalendar(num);
                    event.preventDefault();
                }
            });
        },
        updateNavAriaLabels: function (num) {
            const cal = DateTimeShortcuts.calendars[num];
            const cal_box = document.getElementById(
                DateTimeShortcuts.calendarDivName1 + num,
            );
            const prevMonth =
                CalendarNamespace.monthsOfYear[(cal.currentMonth + 10) % 12];
            const prevYear =
                cal.currentMonth === 1 ? cal.currentYear - 1 : cal.currentYear;
            cal_box
                .querySelector(".calendarnav-previous")
                .setAttribute(
                    "aria-label",
                    interpolate(
                        gettext("Previous (%(month)s %(year)s)"),
                        { month: prevMonth, year: prevYear },
                        true,
                    ),
                );

            const nextMonth =
                CalendarNamespace.monthsOfYear[cal.currentMonth % 12];
            const nextYear =
                cal.currentMonth === 12 ? cal.currentYear + 1 : cal.currentYear;
            cal_box
                .querySelector(".calendarnav-next")
                .setAttribute(
                    "aria-label",
                    interpolate(
                        gettext("Next (%(month)s %(year)s)"),
                        { month: nextMonth, year: nextYear },
                        true,
                    ),
                );
        },
        openCalendar: function (num) {
            const cal_box = document.getElementById(
                DateTimeShortcuts.calendarDivName1 + num,
            );
            const cal_link = document.getElementById(
                DateTimeShortcuts.calendarLinkName + num,
            );
            const inp = DateTimeShortcuts.calendarInputs[num];

            // Determine if the current value in the input has a valid date.
            // If so, draw the calendar with that date's year and month.
            if (inp.value) {
                const format = get_format("DATE_INPUT_FORMATS")[0];
                const selected = inp.value.strptime(format);
                const year = selected.getUTCFullYear();
                const month = selected.getUTCMonth() + 1;
                const re = /\d{4}/;
                if (re.test(year.toString()) && month >= 1 && month <= 12) {
                    DateTimeShortcuts.calendars[num].drawDate(
                        month,
                        year,
                        selected,
                    );
                }
            }

            // Recalculate the calendarbox position
            // is it left-to-right or right-to-left layout ?
            if (window.getComputedStyle(document.body).direction !== "rtl") {
                cal_box.style.left = findPosX(cal_link) + 17 + "px";
            } else {
                // since style's width is in em, it'd be tough to calculate
                // px value of it. let's use an estimated px for now
                cal_box.style.right = findPosX(cal_link) - 180 + "px";
            }
            cal_box.style.top = Math.max(0, findPosY(cal_link) - 75) + "px";

            cal_box.showModal();
            DateTimeShortcuts.updateNavAriaLabels(num);
            const calendarDiv = cal_box.querySelector(
                "#" + DateTimeShortcuts.calendarDivName2 + num,
            );
            if (calendarDiv) {
                // Focus on selected date, today, or first available date
                const focusElement =
                    cal_box.querySelector("td.selected a") ||
                    cal_box.querySelector("td.today a") ||
                    cal_box.querySelector("td a");
                focusElement?.focus();
            }
        },
        dismissCalendar: function (num) {
            document
                .getElementById(DateTimeShortcuts.calendarDivName1 + num)
                .close();
        },
        drawPrev: function (num) {
            DateTimeShortcuts.calendars[num].drawPreviousMonth();
            DateTimeShortcuts.updateNavAriaLabels(num);
        },
        drawNext: function (num) {
            DateTimeShortcuts.calendars[num].drawNextMonth();
            DateTimeShortcuts.updateNavAriaLabels(num);
        },
        handleCalendarCallback: function (num) {
            const format = get_format("DATE_INPUT_FORMATS")[0];
            return function (y, m, d) {
                DateTimeShortcuts.calendarInputs[num].value = new Date(
                    y,
                    m - 1,
                    d,
                ).strftime(format);
                DateTimeShortcuts.calendarInputs[num].focus();
                DateTimeShortcuts.dismissCalendar(num);
            };
        },
        handleCalendarQuickLink: function (num, offset) {
            const d = DateTimeShortcuts.now();
            d.setDate(d.getDate() + offset);
            DateTimeShortcuts.calendarInputs[num].value = d.strftime(
                get_format("DATE_INPUT_FORMATS")[0],
            );
            DateTimeShortcuts.calendarInputs[num].focus();
            DateTimeShortcuts.dismissCalendar(num);
        },
    };

    window.addEventListener("load", DateTimeShortcuts.init);
    window.DateTimeShortcuts = DateTimeShortcuts;
}

/*global SelectBox, interpolate*/
// Handles related-objects functionality: lookup link for raw_id_fields
// and Add Another links.
"use strict";
{
    const $ = django.jQuery;
    let popupIndex = 0;
    const relatedWindows = [];

    function dismissChildPopups() {
        relatedWindows.forEach(function (win) {
            if (!win.closed) {
                win.dismissChildPopups();
                win.close();
            }
        });
    }

    function setPopupIndex() {
        if (document.getElementsByName("_popup").length > 0) {
            const index = window.name.lastIndexOf("__") + 2;
            popupIndex = parseInt(window.name.substring(index));
        } else {
            popupIndex = 0;
        }
    }

    function addPopupIndex(name) {
        return name + "__" + (popupIndex + 1);
    }

    function removePopupIndex(name) {
        return name.replace(new RegExp("__" + (popupIndex + 1) + "$"), "");
    }

    function showAdminPopup(triggeringLink, name_regexp, add_popup) {
        const name = addPopupIndex(triggeringLink.id.replace(name_regexp, ""));
        const href = new URL(triggeringLink.href);
        if (add_popup) {
            href.searchParams.set("_popup", 1);
        }
        const win = window.open(
            href,
            name,
            "height=500,width=800,resizable=yes,scrollbars=yes",
        );
        relatedWindows.push(win);
        win.focus();
        return false;
    }

    function showRelatedObjectLookupPopup(triggeringLink) {
        return showAdminPopup(triggeringLink, /^lookup_/, true);
    }

    function dismissRelatedLookupPopup(win, chosenId) {
        const name = removePopupIndex(win.name);
        const elem = document.getElementById(name);
        if (
            elem.classList.contains("vManyToManyRawIdAdminField") &&
            elem.value
        ) {
            elem.value += "," + chosenId;
        } else {
            elem.value = chosenId;
        }
        $(elem).trigger("change");
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function showRelatedObjectPopup(triggeringLink) {
        return showAdminPopup(triggeringLink, /^(change|add|delete)_/, false);
    }

    function updateRelatedObjectLinks(triggeringLink) {
        const $this = $(triggeringLink);
        const siblings = $this.nextAll(
            ".view-related, .change-related, .delete-related",
        );
        if (!siblings.length) {
            return;
        }
        const value = $this.val();
        if (value) {
            siblings.each(function () {
                const elm = $(this);
                elm.attr(
                    "href",
                    elm.attr("data-href-template").replace("__fk__", value),
                );
                elm.removeAttr("aria-disabled");
            });
        } else {
            siblings.removeAttr("href");
            siblings.attr("aria-disabled", true);
        }
    }

    function updateRelatedSelectsOptions(
        currentSelect,
        win,
        objId,
        newRepr,
        newId,
        skipIds = [],
    ) {
        // After create/edit a model from the options next to the current
        // select (+ or :pencil:) update ForeignKey PK of the rest of selects
        // in the page.

        const path = win.location.pathname;
        // Extract the model from the popup url '.../<model>/add/' or
        // '.../<model>/<id>/change/' depending the action (add or change).
        const modelName =
            path.split("/")[path.split("/").length - (objId ? 4 : 3)];
        // Select elements with a specific model reference and context of "available-source".
        const selectsRelated = document.querySelectorAll(
            `[data-model-ref="${modelName}"] [data-context="available-source"]`,
        );

        selectsRelated.forEach(function (select) {
            if (
                currentSelect === select ||
                (skipIds && skipIds.includes(select.id))
            ) {
                return;
            }

            let option = select.querySelector(`option[value="${objId}"]`);

            if (!option) {
                option = new Option(newRepr, newId);
                select.options.add(option);
                // Update SelectBox cache for related fields.
                if (
                    window.SelectBox !== undefined &&
                    !SelectBox.cache[currentSelect.id] &&
                    // Only if SelectBox is managing that field.
                    SelectBox.cache[select.id]
                ) {
                    SelectBox.add_to_cache(select.id, option);
                    // Sort if there are any groups present
                    if (SelectBox.cache[select.id].some((item) => item.group)) {
                        SelectBox.sort(select.id);
                    }
                    SelectBox.redisplay(select.id);
                }
                return;
            }

            option.textContent = newRepr;
            option.value = newId;
        });
    }

    function dismissAddRelatedObjectPopup(win, newId, newRepr, optgroup) {
        const name = removePopupIndex(win.name);
        const elem = document.getElementById(name);
        if (elem) {
            const elemName = elem.nodeName.toUpperCase();
            if (elemName === "SELECT") {
                elem.options[elem.options.length] = new Option(
                    newRepr,
                    newId,
                    true,
                    true,
                );
                updateRelatedSelectsOptions(elem, win, null, newRepr, newId);
            } else if (elemName === "INPUT") {
                if (
                    elem.classList.contains("vManyToManyRawIdAdminField") &&
                    elem.value
                ) {
                    elem.value += "," + newId;
                } else {
                    elem.value = newId;
                }
            }
            // Trigger a change event to update related links if required.
            $(elem).trigger("change");
        } else {
            const toId = name + "_to";
            const toElem = document.getElementById(toId);
            const newOption = new Option(newRepr, newId);
            newOption.group = optgroup;
            SelectBox.add_to_cache(toId, newOption);
            // Sort if there are any groups present
            if (SelectBox.cache[toId].some((item) => item.group)) {
                SelectBox.sort(toId);
            }
            SelectBox.redisplay(toId);
            if (toElem && toElem.nodeName.toUpperCase() === "SELECT") {
                const skipIds = [name + "_from"];
                updateRelatedSelectsOptions(
                    toElem,
                    win,
                    null,
                    newRepr,
                    newId,
                    skipIds,
                );
            }
        }
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function dismissChangeRelatedObjectPopup(win, objId, newRepr, newId) {
        const id = removePopupIndex(win.name.replace(/^edit_/, ""));
        const selectsSelector = interpolate("#%s, #%s_from, #%s_to", [
            id,
            id,
            id,
        ]);
        const selects = $(selectsSelector);
        selects
            .find("option")
            .each(function () {
                if (this.value === objId) {
                    this.textContent = newRepr;
                    this.value = newId;
                }
            })
            .trigger("change");
        updateRelatedSelectsOptions(selects[0], win, objId, newRepr, newId);
        selects
            .next()
            .find(".select2-selection__rendered")
            .each(function () {
                // The element can have a clear button as a child.
                // Use the lastChild to modify only the displayed value.
                this.lastChild.textContent = newRepr;
                this.title = newRepr;
            });
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    function dismissDeleteRelatedObjectPopup(win, objId) {
        const id = removePopupIndex(win.name.replace(/^delete_/, ""));
        const selectsSelector = interpolate("#%s, #%s_from, #%s_to", [
            id,
            id,
            id,
        ]);
        const selects = $(selectsSelector);
        selects
            .find("option")
            .each(function () {
                if (this.value === objId) {
                    $(this).remove();
                }
            })
            .trigger("change");
        const index = relatedWindows.indexOf(win);
        if (index > -1) {
            relatedWindows.splice(index, 1);
        }
        win.close();
    }

    window.showRelatedObjectLookupPopup = showRelatedObjectLookupPopup;
    window.dismissRelatedLookupPopup = dismissRelatedLookupPopup;
    window.showRelatedObjectPopup = showRelatedObjectPopup;
    window.updateRelatedObjectLinks = updateRelatedObjectLinks;
    window.dismissAddRelatedObjectPopup = dismissAddRelatedObjectPopup;
    window.dismissChangeRelatedObjectPopup = dismissChangeRelatedObjectPopup;
    window.dismissDeleteRelatedObjectPopup = dismissDeleteRelatedObjectPopup;
    window.dismissChildPopups = dismissChildPopups;
    window.relatedWindows = relatedWindows;

    // Kept for backward compatibility
    window.showAddAnotherPopup = showRelatedObjectPopup;
    window.dismissAddAnotherPopup = dismissAddRelatedObjectPopup;

    window.addEventListener("pagehide", function (evt) {
        window.dismissChildPopups();
    });

    $(document).ready(function () {
        setPopupIndex();
        $("a[data-popup-opener]").on("click", function (event) {
            event.preventDefault();
            opener.dismissRelatedLookupPopup(
                window,
                $(this).data("popup-opener"),
            );
        });
        $("body").on(
            "click",
            '.related-widget-wrapper-link[data-popup="yes"]',
            function (e) {
