            });
            filter_input.addEventListener("keyup", function (e) {
                SelectFilter.filter_key_up(e, field_id, "_from");
            });
            filter_input.addEventListener("keydown", function (e) {
                SelectFilter.filter_key_down(e, field_id, "_from", "_to");
            });
            filter_selected_input.addEventListener("keypress", function (e) {
                SelectFilter.filter_key_press(e, field_id, "_to", "_from");
            });
            filter_selected_input.addEventListener("keyup", function (e) {
                SelectFilter.filter_key_up(
                    e,
                    field_id,
                    "_to",
                    "_selected_input",
                );
            });
            filter_selected_input.addEventListener("keydown", function (e) {
                SelectFilter.filter_key_down(e, field_id, "_to", "_from");
            });
            selector_div.addEventListener("change", function (e) {
                if (e.target.tagName === "SELECT") {
                    SelectFilter.refresh_icons(field_id);
                }
            });
            selector_div.addEventListener("dblclick", function (e) {
                if (e.target.tagName === "OPTION") {
                    if (e.target.closest("select").id === field_id + "_to") {
                        SelectBox.move(field_id + "_to", field_id + "_from");
                    } else {
                        SelectBox.move(field_id + "_from", field_id + "_to");
                    }
                    SelectFilter.refresh_icons(field_id);
                }
            });
            from_box.closest("form").addEventListener("submit", function () {
                SelectBox.filter(field_id + "_to", "");
                SelectBox.select_all(field_id + "_to");
            });
            SelectBox.init(field_id + "_from");
            SelectBox.init(field_id + "_to");
            // Move selected from_box options to to_box
            SelectBox.move(field_id + "_from", field_id + "_to");

            // Initial icon refresh
            SelectFilter.refresh_icons(field_id);
        },
        any_selected: function (field) {
            // Temporarily add the required attribute and check validity.
            field.required = true;
            const any_selected = field.checkValidity();
            field.required = false;
            return any_selected;
        },
        refresh_filtered_warning: function (field_id) {
            const count = SelectBox.get_hidden_node_count(field_id + "_to");
            const selector = document.getElementById(
                field_id + "_selector_chosen",
            );
            const warning = document.getElementById(
                field_id + "_list-footer-display-text",
            );
            selector.className = selector.className.replace(
                "selector-chosen--with-filtered",
                "",
            );
            warning.textContent = interpolate(
                ngettext(
                    "%s selected option not visible",
                    "%s selected options not visible",
                    count,
                ),
                [count],
            );
            if (count > 0) {
                selector.className += " selector-chosen--with-filtered";
            }
        },
        refresh_filtered_selects: function (field_id) {
            SelectBox.filter(
                field_id + "_from",
                document.getElementById(field_id + "_input").value,
            );
            SelectBox.filter(
                field_id + "_to",
                document.getElementById(field_id + "_selected_input").value,
            );
        },
        refresh_icons: function (field_id) {
            const from = document.getElementById(field_id + "_from");
            const to = document.getElementById(field_id + "_to");
            // Disabled if no items are selected.
            document.getElementById(field_id + "_add").disabled =
                !SelectFilter.any_selected(from);
            document.getElementById(field_id + "_remove").disabled =
                !SelectFilter.any_selected(to);
            // Disabled if the corresponding box is empty.
            document.getElementById(field_id + "_add_all").disabled =
                !from.querySelector("option");
            document.getElementById(field_id + "_remove_all").disabled =
                !to.querySelector("option");
        },
        filter_key_press: function (event, field_id, source, target) {
            const source_box = document.getElementById(field_id + source);
            // don't submit form if user pressed Enter
            if (
                (event.which && event.which === 13) ||
                (event.keyCode && event.keyCode === 13)
            ) {
                source_box.selectedIndex = 0;
                SelectBox.move(field_id + source, field_id + target);
                source_box.selectedIndex = 0;
                event.preventDefault();
            }
        },
        filter_key_up: function (event, field_id, source, filter_input) {
            const input = filter_input || "_input";
            const source_box = document.getElementById(field_id + source);
            const temp = source_box.selectedIndex;
            SelectBox.filter(
                field_id + source,
                document.getElementById(field_id + input).value,
            );
            source_box.selectedIndex = temp;
            SelectFilter.refresh_filtered_warning(field_id);
            SelectFilter.refresh_icons(field_id);
        },
        filter_key_down: function (event, field_id, source, target) {
            const source_box = document.getElementById(field_id + source);
            // right key (39) or left key (37)
            const direction = source === "_from" ? 39 : 37;
            // right arrow -- move across
            if (
                (event.which && event.which === direction) ||
                (event.keyCode && event.keyCode === direction)
            ) {
                const old_index = source_box.selectedIndex;
                SelectBox.move(field_id + source, field_id + target);
                SelectFilter.refresh_filtered_selects(field_id);
                SelectFilter.refresh_filtered_warning(field_id);
                source_box.selectedIndex =
                    old_index === source_box.length
                        ? source_box.length - 1
                        : old_index;
                return;
            }
            // down arrow -- wrap around
            if (
                (event.which && event.which === 40) ||
                (event.keyCode && event.keyCode === 40)
            ) {
                source_box.selectedIndex =
                    source_box.length === source_box.selectedIndex + 1
                        ? 0
                        : source_box.selectedIndex + 1;
            }
            // up arrow -- wrap around
            if (
                (event.which && event.which === 38) ||
                (event.keyCode && event.keyCode === 38)
            ) {
                source_box.selectedIndex =
                    source_box.selectedIndex === 0
                        ? source_box.length - 1
                        : source_box.selectedIndex - 1;
            }
        },
    };

    window.addEventListener("load", function (e) {
        document
            .querySelectorAll("select.selectfilter, select.selectfilterstacked")
            .forEach(function (el) {
                const data = el.dataset;
                SelectFilter.init(
                    el.id,
                    data.fieldName,
                    parseInt(data.isStacked, 10),
                );
            });
    });
}

"use strict";
{
    function setTheme(mode) {
        if (mode !== "light" && mode !== "dark" && mode !== "auto") {
            console.error(
                `Got invalid theme mode: ${mode}. Resetting to auto.`,
            );
            mode = "auto";
        }
        document.documentElement.dataset.theme = mode;
        localStorage.setItem("theme", mode);
    }

    function cycleTheme() {
        const currentTheme = localStorage.getItem("theme") || "auto";
        const prefersDark = window.matchMedia(
            "(prefers-color-scheme: dark)",
        ).matches;

        if (prefersDark) {
            // Auto (dark) -> Light -> Dark
            if (currentTheme === "auto") {
                setTheme("light");
            } else if (currentTheme === "light") {
                setTheme("dark");
            } else {
                setTheme("auto");
            }
        } else {
            // Auto (light) -> Dark -> Light
            if (currentTheme === "auto") {
                setTheme("dark");
            } else if (currentTheme === "dark") {
                setTheme("light");
            } else {
                setTheme("auto");
            }
        }
    }

    function initTheme() {
        // set theme defined in localStorage if there is one, or fallback to auto mode
        const currentTheme = localStorage.getItem("theme");
        currentTheme ? setTheme(currentTheme) : setTheme("auto");
    }

    window.addEventListener("load", function (_) {
        const buttons = document.getElementsByClassName("theme-toggle");
        Array.from(buttons).forEach((btn) => {
            btn.addEventListener("click", cycleTheme);
        });
    });

    initTheme();
}

from django import template
from django.contrib.admin.options import EMPTY_VALUE_STRING
from django.contrib.admin.utils import display_for_value
from django.template.defaultfilters import _walk_items, stringfilter
from django.utils.html import conditional_escape
from django.utils.safestring import mark_safe
from django.utils.translation import ngettext

register = template.Library()


@register.filter
@stringfilter
def to_object_display_value(value):
    return display_for_value(str(value), EMPTY_VALUE_STRING)


@register.filter(is_safe=True, needs_autoescape=True)
def truncated_unordered_list(value, max_items, autoescape=True):
    """
    Render an unordered list, showing at most ``max_items`` items and a
    "...and N more objects." item at the end.

    Usage::

        {{ deleted_objects|truncated_unordered_list:100 }}
    """

    has_unlimited_items = max_items is None
    if not has_unlimited_items:
        max_items = int(max_items)
        if max_items <= 0:
            return mark_safe("")

    if autoescape:
        escaper = conditional_escape
    else:

        def escaper(x):
            return x

    item_count = 0

    def list_formatter(item_list, tabs=1):
        nonlocal item_count
        indent = "\t" * tabs
        output = []
        for item, children in _walk_items(item_list):
            sublist = ""
            item_count += 1
            should_display_item = has_unlimited_items or 0 < item_count <= max_items
            if children:
                sublist = "\n%s<ul>\n%s\n%s</ul>\n%s" % (
                    indent,
                    list_formatter(children, tabs + 1),
                    indent,
                    indent,
                )

            if should_display_item:
                output.append("%s<li>%s%s</li>" % (indent, escaper(item), sublist))

        return "\n".join(output)

    rendered_object_list = list_formatter(value)
    remaining_objects_message = ""

    if not has_unlimited_items and item_count > max_items:
        remaining_object_count = item_count - max_items
        remaining_objects_message = "\n\t<li>%s</li>" % (
            ngettext(
                "…and %(count)d more object.",
                "…and %(count)d more objects.",
                remaining_object_count,
            )
            % {"count": remaining_object_count}
        )

    return mark_safe(rendered_object_list + remaining_objects_message)

